  ["# 1024 -> 512 -> 256 -> 128 -> 64 -> 32 -> 16 -> 8 -> 4 -> 2 -> 1\n# ___ halvings: math.log2(1024)\n"] = "# 1024 -> 512 -> 256 -> 128 -> 64 -> 32 -> 16 -> 8 -> 4 -> 2 -> 1\n# ___ 次减半：math.log2(1024)\n",
  ["# 400 URLs, threads are fine here:\n# the GIL is ___ while the socket waits\nrequests.get(url)\n"] = "# 400 个 URL，这里用线程就行：\n# socket 等待时 GIL 会被 ___\nrequests.get(url)\n",
  ["# 400 supplier calls  -> ThreadPoolExecutor\n# 400 image resizes   -> ___PoolExecutor\n"] = "# 400 个供应商调用  -> ThreadPoolExecutor\n# 400 张图要缩       -> ___PoolExecutor\n",
  ["# 8 threads, 8 cores, one core busy\n# the reason has three letters: the ___\nimport threading\n"] = "# 8 条线程、8 个核，只有一个核忙\n# 原因只有三个字母：___\nimport threading\n",
  ["# One thread runs Python bytecode at a time: the ___.\n# Threads overlap I/O and sleep, not CPU work.\n# For CPU-bound work use multiprocessing.\n"] = "# 一次只有一个线程运行 Python 字节码：___。\n# 线程重叠 I/O 和 sleep，不重叠 CPU 工作。\n# CPU 密集型工作用 multiprocessing。\n",
  ["# bisect on an unsorted list returns nonsense.\n# Precondition: a is ___ ascending.\na.sort()\ni = bisect.bisect_left(a, 38)\n"] = "# 对未排序列表做 bisect 会返回胡话。\n# 前提：a 是升序 ___。\na.sort()\ni = bisect.bisect_left(a, 38)\n",
  ["# level 1: merge 2 halves      -> n items moved\n# level 2: merge 4 quarters    -> n items moved\n# each level: ___ ; levels: log n ; total: n log n\n"] = "# 第 1 层：合并 2 个一半      -> 移动 n 项\n# 第 2 层：合并 4 个四分之一  -> 移动 n 项\n# 每层：___ ；层数：log n ；总计：n log n\n",
  ["# n = 100\n# pairs = 100 * 99 // 2 = ___\n# still O(n^2): the /2 is a constant\n"] = "# n = 100\n# 对数 = 100 * 99 // 2 = ___\n# 仍然 O(n^2)：/2 是常数\n",
  ["# n = 1000 -> items[3] : 1 step\n# n = 2000 -> items[3] : 1 step\n# the cost stays the ___\n"] = "# n = 1000 -> items[3] : 1 步\n# n = 2000 -> items[3] : 1 步\n# 代价保持 the ___\n",
  ["# process 1: python3 -> its own GIL\n# process 2: python3 -> its own ___\n# two cores at 100%\n"] = "# 进程 1：python3 -> 自己的 GIL\n# 进程 2：python3 -> 自己的 ___\n# 两个核都 100%\n",
  ["# quicksort halves the range each level on average\n# depth ~ log2(n) frames on the stack: O(___) space\n# (naive fib without cache: depth n, RecursionError near 1000)\n"] = "# 快速排序平均每层把范围减半\n# 深度 ~ 栈上 log2(n) 个帧：O(___) 空间\n# （没有 cache 的朴素 fib：深度 n，接近 1000 就 RecursionError）\n",
  ["# starts a comment. There is no block comment; a triple-quoted string at the top of a def is a docstring."] = "# 开始注释。没有块注释；def 顶部的三引号字符串是 docstring。",
  ["# without cache: 2^n calls\n# with cache: fib(0) .. fib(n), each once -> O(___)\n"] = "# 没有 cache：2^n 次调用\n# 有 cache：fib(0) .. fib(n)，每个一次 -> O(___)\n",
  ['#[___(Debug)]\nstruct Order { qty: u32 }\n\nlet o = Order { qty: 2 };\nprintln!("{:?}", o);        // Order { qty: 2 }\n'] = '#[___(Debug)]\nstruct Order { qty: u32 }\n\nlet o = Order { qty: 2 };\nprintln!("{:?}", o);        // Order { qty: 2 }\n',
  ["#[derive(Clone, Debug)] generates the impls. Also common: PartialEq, Default, Copy for small types."] = "#[derive(Clone, Debug)] 生成这些 impl。同样常见：PartialEq、Default，小类型还有 Copy。",
  ["#[derive(Debug, Clone, PartialEq)] generates common traits. {:?} needs Debug. The till prints the order and the afternoon set is sold."] = "#[derive(Debug, Clone, PartialEq)] 生成常用 trait。{:?} 需要 Debug。收银机打印出订单，下午茶套餐卖出去了。",
  ['#[derive(Default, Debug)]\nstruct Tray { buns: u32, teas: u32 }\n// An empty tray, all zeros, without typing them.\nlet empty = Tray::___();\nprintln!("{empty:?}");\n'] = '#[derive(Default, Debug)]\nstruct Tray { buns: u32, teas: u32 }\n// 一个空托盘，全是零，不用逐个敲。\nlet empty = Tray::___();\nprintln!("{empty:?}");\n',
  ['#[derive(Serialize, Deserialize)]\nstruct Order {\n    #[serde(___ = "dish")]\n    name: String,\n    qty: u32,\n}\n// {"dish":"toast","qty":2} now fills name\n'] = '#[derive(Serialize, Deserialize)]\nstruct Order {\n    #[serde(___ = "dish")]\n    name: String,\n    qty: u32,\n}\n// {"dish":"toast","qty":2} 现在会填进 name\n',
  ['#[derive(Serialize, Deserialize)]\nstruct Order {\n    name: String,\n    #[serde(___ = "Option::is_none")]\n    note: Option<String>,\n}\n// None -> {"name":"toast"}   Some -> {"name":..,"note":..}\n'] = '#[derive(Serialize, Deserialize)]\nstruct Order {\n    name: String,\n    #[serde(___ = "Option::is_none")]\n    note: Option<String>,\n}\n// None -> {"name":"toast"}   Some -> {"name":..,"note":..}\n',
  ['#[serde(rename = "dish")] is the Go json tag. rename_all = "camelCase" on the struct is common.'] = '#[serde(rename = "dish")] 就是 Go 的 json tag。struct 上写 rename_all = "camelCase" 很常见。',
  ["#[tokio::main] builds the runtime and block_on(main()). Use #[tokio::test] in tests."] = "#[tokio::main] 搭好运行时并 block_on(main())。测试里用 #[tokio::test]。",
  ['$ ___ shop.py\nshop.py:12: error: Incompatible return value type\n    (got "None", expected "str")\nFound 1 error in 1 file\n'] = '$ ___ shop.py\nshop.py:12: error: Incompatible return value type\n    (got "None", expected "str")\nFound 1 error in 1 file\n',
  ["$ cargo ___\n   Compiling delivery v0.1.0\nrunning 2 checks\nqty_parses ....... ok\neta_is_positive .. ok\nresult: ok. 2 passed; 0 failed\n"] = "$ cargo ___\n   Compiling delivery v0.1.0\nrunning 2 checks\nqty_parses ....... ok\neta_is_positive .. ok\nresult: ok. 2 passed; 0 failed\n",
  ['$ cargo ___\n$ git diff --stat\n src/main.rs | 14 ++++++-------\n$ cargo ___ --check && echo "clean"\n'] = '$ cargo ___\n$ git diff --stat\n src/main.rs | 14 ++++++-------\n$ cargo ___ --check && echo "clean"\n',
  ["$ cargo ___\nwarning: this `.into_iter()` call is equivalent to `.iter()`\n  --> src/main.rs:12:24\n   = help: consider using `.iter()`\n"] = "$ cargo ___\nwarning: this `.into_iter()` call is equivalent to `.iter()`\n  --> src/main.rs:12:24\n   = help: consider using `.iter()`\n",
  ["$ cargo ___ delivery\n     Created binary (application) `delivery` package\n$ ls delivery\nCargo.toml  src/main.rs\n"] = "$ cargo ___ delivery\n     Created binary (application) `delivery` package\n$ ls delivery\nCargo.toml  src/main.rs\n",
  ["$ cargo ___ reqwest --features json\n    Updating crates.io index\n      Adding reqwest v0.12 to dependencies\n"] = "$ cargo ___ reqwest --features json\n    Updating crates.io index\n      Adding reqwest v0.12 to dependencies\n",
  ["$ cargo build --___\n   Compiling delivery v0.1.0\n    Finished [optimized] target(s) in 41.2s\n"] = "$ cargo build --___\n   Compiling delivery v0.1.0\n    Finished [optimized] target(s) in 41.2s\n",
  ["$ cat go.___\ngithub.com/alex/luckymac v1.2.0 h1:9fK2...Qw=\ngithub.com/alex/luckymac v1.2.0/go.mod h1:Lm0...c8=\n"] = "$ cat go.___\ngithub.com/alex/luckymac v1.2.0 h1:9fK2...Qw=\ngithub.com/alex/luckymac v1.2.0/go.mod h1:Lm0...c8=\n",
  ["$ cd luckymac/menu\n$ go env ___\n/Users/alex/luckymac/go.mod\n"] = "$ cd luckymac/menu\n$ go env ___\n/Users/alex/luckymac/go.mod\n",
  ["$ git ___ v1.0.0\n$ git push origin v1.0.0\n"] = "$ git ___ v1.0.0\n$ git push origin v1.0.0\n",
  ['$ git config --global \\\n    url."git@github.com:".___ "https://github.com/"\n'] = '$ git config --global \\\n    url."git@github.com:".___ "https://github.com/"\n',
  ["$ git remote -v\norigin  git@github.com:alex/luckymac.git (push)\n$ go mod init ___\ngo: creating new go.mod\n"] = "$ git remote -v\norigin  git@github.com:alex/luckymac.git (push)\n$ go mod init ___\ngo: creating new go.mod\n",
  ["$ go ___ -m all\ngithub.com/siuming/cousinshop\ngithub.com/alex/luckymac v1.0.0\ngithub.com/goccy/go-json v0.10.3\n"] = "$ go ___ -m all\ngithub.com/siuming/cousinshop\ngithub.com/alex/luckymac v1.0.0\ngithub.com/goccy/go-json v0.10.3\n",
  ["$ go ___ -o delivery .    # one static file\n$ ./delivery\n"] = "$ go ___ -o delivery .    # one static file\n$ ./delivery\n",
  ["$ go ___ ./...    # static checks, no run\n$ go fmt ./...    # and gofmt every file\n"] = "$ go ___ ./...    # static checks, no run\n$ go fmt ./...    # and gofmt every file\n",
  ["$ go ___ github.com/alex/luckymac@v1.2.0\ngo: downloading github.com/alex/luckymac v1.2.0\ngo: added github.com/alex/luckymac v1.2.0\n"] = "$ go ___ github.com/alex/luckymac@v1.2.0\ngo: downloading github.com/alex/luckymac v1.2.0\ngo: added github.com/alex/luckymac v1.2.0\n",
  ["$ go ___ init luckymac/delivery\ngo: creating new go.mod: module luckymac/delivery\n"] = "$ go ___ init luckymac/delivery\ngo: creating new go.mod: module luckymac/delivery\n",
  ["$ go build ./...\nmain.go:6:2: no required module provides package\n    github.com/alex/luckymac/menu; to add it:\n    go mod ___\n"] = "$ go build ./...\nmain.go:6:2: no required module provides package\n    github.com/alex/luckymac/menu; to add it:\n    go mod ___\n",
  ["$ go clean -___\n$ go build ./...     # everything downloads again, once\n"] = "$ go clean -___\n$ go build ./...     # 一切重新下载一次，只一次\n",
  ["$ go env -w ___=github.com/luckymac-hk/*\n$ go get github.com/luckymac-hk/kitchen@latest\n"] = "$ go env -w ___=github.com/luckymac-hk/*\n$ go get github.com/luckymac-hk/kitchen@latest\n",
  ["$ go env GO111MODULE\n___\n# modules everywhere, go.mod or not\n"] = "$ go env GO111MODULE\n___\n# 到处都是模块模式，有没有 go.mod 都一样\n",
  ["$ go env GOPROXY\nhttps://proxy.golang.org,___\n"] = "$ go env GOPROXY\nhttps://proxy.golang.org,___\n",
  ["$ go env GOSUMDB\n___.golang.org\n"] = "$ go env GOSUMDB\n___.golang.org\n",
  ["$ go get github.com/alex/luckymac@___\ngo: upgraded github.com/alex/luckymac v0.3.0 => v1.0.0\n"] = "$ go get github.com/alex/luckymac@___\ngo: upgraded github.com/alex/luckymac v0.3.0 => v1.0.0\n",
  ["$ go mod ___\n$ ls\ngo.mod  go.sum  main.go  menu/  ___/\n$ go build ./...      # reads ___/ automatically\n"] = "$ go mod ___\n$ ls\ngo.mod  go.sum  main.go  menu/  ___/\n$ go build ./...      # 自动读取 ___/\n",
  ["$ go mod ___    # sync go.mod with the imports\n"] = "$ go mod ___    # sync go.mod with the imports\n",
  ["$ go test -___ ./kitchen\nWARNING: DATA RACE\nWrite at 0x00c0000b4010 by goroutine 8\nPrevious read by goroutine 7\n"] = "$ go test -___ ./kitchen\nWARNING: DATA RACE\nWrite at 0x00c0000b4010 by goroutine 8\nPrevious read by goroutine 7\n",
  ["$ go test ___ ./...\nWARNING: DATA RACE\nWrite at 0x00c0000 by goroutine 7\n"] = "$ go test ___ ./...\nWARNING: DATA RACE\nWrite at 0x00c0000 by goroutine 7\n",
  ["$ ls\ncousinshop/  luckymac/\n$ go ___ init ./cousinshop ./luckymac\n"] = "$ ls\ncousinshop/  luckymac/\n$ go ___ init ./cousinshop ./luckymac\n",
  ["$ ls $(go env GOMODCACHE)\ncache/  github.com/\n$ go env GOMODCACHE\n/Users/siuming/go/pkg/___\n"] = "$ ls $(go env GOMODCACHE)\ncache/  github.com/\n$ go env GOMODCACHE\n/Users/siuming/go/pkg/___\n",
  ['$ python3.13t -c "import sys; print(sys._is_gil_enabled())"\nFalse\n# this is the ___-threaded build (PEP 703)\n'] = '$ python3.13t -c "import sys; print(sys._is_gil_enabled())"\nFalse\n# 这就是 ___-threaded 构建（PEP 703）\n',
  ["%d / %d clear"] = "%d / %d 通关",
  ["%s  MAP %d/%d  %s"] = "%s  地图 %d/%d  %s",
  ["%s TRACK"] = "%s 路线",
  ["%v value, %+v with names, %#v as Go syntax, %T the type."] = "%v 值，%+v 带字段名，%#v Go 语法，%T 类型。",
  ["%v with a plus. %#v adds the type name too; %T prints only the type."] = "%v 加一个加号。%#v 还会加上类型名；%T 只打印类型。",
  ["%w builds a chain. %v would flatten it to text and lose the cause."] = "%w 构成一条链。%v 会把它压平成文本，丢掉原因。",
  ["&'a str: the output lives at least as long as the shorter of a and b. Lifetimes describe; they never extend anything."] = "&'a str：输出至少活得和 a、b 中较短的一样久。生命周期只是描述；从不延长任何东西。",
  ["&'static str lives for the whole program. String literals are 'static; a returned reference with no input to borrow from must be too."] = "&'static str 活满整个程序。字符串字面量是 'static；没有输入可借的返回引用也必须是。",
  ["&String is a shared borrow: read only, any number at once, the owner keeps the value."] = "&String 是共享借用：只读，可以同时有任意多个，所有者仍保有值。",
  ["&T{} is the usual way to make a pointer to a struct. p.Field works without (*p)."] = "&T{} 是创建 struct 指针的常用写法。p.Field 不用写 (*p)。",
  ["&dyn Cook is a trait object: a pointer plus a vtable. Go interfaces work the same way underneath."] = "&dyn Cook 是 trait 对象：一个指针加一个 vtable。Go 的 interface 底层也是这么干的。",
  ["&mut a. While r lives, no other borrow of a may exist: exactly 1 &mut, or many &, never both."] = "&mut a。r 活着的时候，a 不能有别的借用：要么恰好 1 个 &mut，要么多个 &，绝不同时。",
  ["&prices[1..3] is a slice of type &[i32]: a borrowed window, no copy. [1..] and [..2] also work."] = "&prices[1..3] 是类型为 &[i32] 的切片：借用的窗口，不复制。[1..] 和 [..2] 也行。",
  ["&str is a view into text; String owns it. Take &str in parameters, return String when you build new text. The receipt prints once."] = "&str 是文本的视图；String 拥有文本。参数收 &str，构造新文本时返回 String。收据只打印一次。",
  ["(hi - lo) / 2. Each pass throws away half the range. usize overflow panics in debug builds, so the subtraction form matters."] = "(hi - lo) / 2。每一轮扔掉一半范围。usize 溢出在 debug 构建里会 panic，所以减法的写法有意义。",
  ["(lo + hi) / 2, or lo + (hi-lo)/2 to dodge overflow. Each pass throws away half the range."] = "(lo + hi) / 2，或者用 lo + (hi-lo)/2 躲开溢出。每一轮扔掉一半范围。",
  ["(lo + hi) // 2. Python ints never overflow, so the plain form is safe. Each pass throws away half the range."] = "(lo + hi) // 2。Python 的 int 永不溢出，所以简单写法是安全的。每一轮扔掉一半范围。",
  ["(ok, err). Check err before using ok. The gate opens."] = "(ok, err)。用 ok 之前先检查 err。闸机开了。",
  ["**opts packs keyword arguments into a dict. The usual names are *args and **kwargs; any name works."] = "**opts 把关键字参数打包成 dict。惯用名是 *args 和 **kwargs；用什么名字都行。",
  ["*Order is a pointer. Methods that change the struct use a *T receiver."] = "*Order 是指针。修改 struct 的方法用 *T 接收者。",
  ["*http.Request is everything the client sent. Query().Get reads ?item=."] = "*http.Request 是客户端发来的一切。Query().Get 读取 ?item=。",
  ["*items packs extra positional arguments into a tuple. Go's ...int. Calling total(*prices) unpacks a list the other way."] = "*items 把多出的位置参数打包成元组。Go 的 ...int。调用 total(*prices) 则反过来把列表拆开。",
  ["+%d XP"] = "+%d XP",
  ["--release turns on opt-level 3 and drops debug checks. Plain cargo build is for development."] = "--release 开启 opt-level 3 并去掉调试检查。不带参数的 cargo build 是给开发用的。",
  ["-> None says: no useful result. mypy then complains if you assign the call. Forty bowls saved."] = "-> None 表示：没有有用的结果。之后你把调用结果赋值 mypy 就会抱怨。救回四十碗。",
  ["-gcflags=-m says o escapes. Where does a shared reference have to live?"] = "-gcflags=-m 说 o escapes。共享的引用必须住在哪里？",
  ["...int is variadic. Call it with sum(a, b, c) or spread a slice: sum(fares...)."] = "...int 是可变参数。可以 sum(a, b, c) 调用，或展开 slice：sum(fares...)。",
  [".await yields to the runtime until the Future is ready. Forget it and nothing runs."] = ".await 把控制权交给运行时，直到 Future 就绪。忘了写它，就什么都不会跑。",
  ['// "abc" is not a number: fall back to zero coins.\nlet coins: u32 = "abc".parse().___(0);\n'] = '// "abc" 不是数字：退回到零个硬币。\nlet coins: u32 = "abc".parse().___(0);\n',
  ["// &Option<T> to Option<&T>: a borrow, not a move.\nfn root_val(tree: &Link) -> Option<i32> {\n    tree.___().map(|n| n.val)\n}\n"] = "// &Option<T> 变 Option<&T>：借用，不是移动。\nfn root_val(tree: &Link) -> Option<i32> {\n    tree.___().map(|n| n.val)\n}\n",
  ["// 1 topping: 2 combos   2 toppings: 4   3 toppings: 8\n// n toppings: ___ combos, and listing them all cannot be faster\n"] = "// 1 种配料：2 种组合   2 种：4   3 种：8\n// n 种配料：___ 种组合，全部列出不可能更快\n",
  ["// 1 topping: 2 combos   2 toppings: 4   3 toppings: 8\n// n toppings: ___ combos; 1u64 << n computes it\n"] = "// 1 种配料：2 种组合   2 种：4   3 种：8\n// n 种配料：___ 种组合；1u64 << n 算出来\n",
  ["// 1024 -> 512 -> 256 -> 128 -> 64 -> 32 -> 16 -> 8 -> 4 -> 2 -> 1\n// ___ halvings: 1024_u32.ilog2()\n"] = "// 1024 -> 512 -> 256 -> 128 -> 64 -> 32 -> 16 -> 8 -> 4 -> 2 -> 1\n// ___ 次减半：1024_u32.ilog2()\n",
  ["// 1024 -> 512 -> 256 -> 128 -> 64 -> 32 -> 16 -> 8 -> 4 -> 2 -> 1\n// ___ halvings: log2(1024)\n"] = "// 1024 -> 512 -> 256 -> 128 -> 64 -> 32 -> 16 -> 8 -> 4 -> 2 -> 1\n// ___ 次减半：log2(1024)\n",
  ['// Any cook must give a name; greet comes for free.\n___ Cook {\n    fn name(&self) -> String;\n    fn greet(&self) -> String {\n        format!("{} at the pass", self.name())\n    }\n}\n'] = '// 任何厨师都得报名字；greet 免费附送。\n___ Cook {\n    fn name(&self) -> String;\n    fn greet(&self) -> String {\n        format!("{} at the pass", self.name())\n    }\n}\n',
  ["// Ask the compiler to write .clone() for Order.\n#[___(Clone, Debug)]\nstruct Order {\n    bun: String,\n    qty: u32,\n}\n"] = "// 让编译器替 Order 写 .clone()。\n#[___(Clone, Debug)]\nstruct Order {\n    bun: String,\n    qty: u32,\n}\n",
  ["// BinarySearch on an unsorted slice returns nonsense.\n// Precondition: a is ___ ascending.\nsort.Ints(a)\ni, found := slices.BinarySearch(a, 38)\n"] = "// 对未排序切片做 BinarySearch 会返回胡话。\n// 前提：a 是升序 ___。\nsort.Ints(a)\ni, found := slices.BinarySearch(a, 38)\n",
  ['// Cargo.toml: [dependencies] has this crate at version 1\nuse ___::Error;\n#[derive(Debug, Error)]\nenum OrderError {\n    #[error("order is empty")]\n    Empty,\n}\n'] = '// Cargo.toml: [dependencies] 里有这个 crate，版本 1\nuse ___::Error;\n#[derive(Debug, Error)]\nenum OrderError {\n    #[error("order is empty")]\n    Empty,\n}\n',
  ['// Cargo.toml: tokio = {version="1", features=["full"]}\n#[___]\nasync fn main() {\n    let eta = fetch_eta(7).await;\n    println!("{eta} min");\n}\n'] = '// Cargo.toml: tokio = {version="1", features=["full"]}\n#[___]\nasync fn main() {\n    let eta = fetch_eta(7).await;\n    println!("{eta} min");\n}\n',
  ["// Debug + Display are done, so the body can stay empty\nimpl ___ for OrderError {}\n"] = "// Debug + Display 都有了，所以函数体可以留空\nimpl ___ for OrderError {}\n",
  ["// Do not communicate by sharing memory;\n// share memory by ___.\norders <- Order{id: 7}\n"] = "// 不要通过共享内存来通信；\n// 要通过 ___ 来共享内存。\norders <- Order{id: 7}\n",
  ['// Grill and Wok in one Vec: each boxed as a trait object.\nlet crew: Vec<___> = vec![Box::new(Grill), Box::new(Wok)];\nfor c in &crew { println!("{}", c.greet()); }\n'] = '// Grill 和 Wok 放进一个 Vec：各自装箱成 trait 对象。\nlet crew: Vec<___> = vec![Box::new(Grill), Box::new(Wok)];\nfor c in &crew { println!("{}", c.greet()); }\n',
  ['// In the terminal, inside the project folder:\n//   $ cargo ___\n// Compiles target/debug/express and starts it.\nfn main() {\n    println!("Lucky Mac Express");\n}\n'] = '// 在终端里，进入项目文件夹：\n//   $ cargo ___\n// 编译 target/debug/express 并启动它。\nfn main() {\n    println!("Lucky Mac Express");\n}\n',
  ['// Keep every handle so the pass can wait for every cook.\nlet mut hs: Vec<___<()>> = Vec::new();\nfor id in 0..3 {\n    hs.push(thread::spawn(move || println!("cook {id}")));\n}\nfor h in hs { h.join().unwrap(); }\n'] = '// 留住每个句柄，出餐口才能等每个厨师。\nlet mut hs: Vec<___<()>> = Vec::new();\nfor id in 0..3 {\n    hs.push(thread::spawn(move || println!("cook {id}")));\n}\nfor h in hs { h.join().unwrap(); }\n',
  ["// Not every table has an order yet.\nfn find(orders: &[(u32, &str)], t: u32) -> ___<String> {\n    for (n, item) in orders {\n        if *n == t { return Some(item.to_string()); }\n    }\n    None\n}\n"] = "// 不是每张桌都点了单。\nfn find(orders: &[(u32, &str)], t: u32) -> ___<String> {\n    for (n, item) in orders {\n        if *n == t { return Some(item.to_string()); }\n    }\n    None\n}\n",
  ['// Nothing here tells parse which number type to build.\nlet qty = "12".parse___().unwrap();\nlet total = qty * 18;\n'] = '// 这里没有东西告诉 parse 要造哪种数字类型。\nlet qty = "12".parse___().unwrap();\nlet total = qty * 18;\n',
  ["// One counter, many cooks: one writer at a time.\nlet sold = Arc::new(___::new(0u32));\n"] = "// 一个计数器，多个厨师：一次只能一个写。\nlet sold = Arc::new(___::new(0u32));\n",
  ["// Only types with this marker may move to another thread.\nfn ship<T: ___ + 'static>(t: T) {\n    thread::spawn(move || drop(t));\n}\nship(Arc::new(5));    // ok: Arc is thread-safe\n// ship(Rc::new(5));  // error: Rc is not\n"] = "// 只有带这个标记的类型才能移到另一个线程。\nfn ship<T: ___ + 'static>(t: T) {\n    thread::spawn(move || drop(t));\n}\nship(Arc::new(5));    // 可以：Arc 线程安全\n// ship(Rc::new(5));  // 报错：Rc 不安全\n",
  ['// Peek without waiting: the till must keep beeping.\nmatch rx.___() {\n    Ok(order) => println!("got {order}"),\n    Err(_) => println!("nothing yet"),\n}\n'] = '// 不等待地看一眼：收银机得继续响。\nmatch rx.___() {\n    Ok(order) => println!("got {order}"),\n    Err(_) => println!("nothing yet"),\n}\n',
  ['// Rc counts on one thread only; this one crosses threads.\nlet menu = ___::new(vec!["bun", "egg tart"]);\nlet m2 = menu.clone();\nthread::spawn(move || println!("{}", m2[0]));\n'] = '// Rc 只能在一个线程上计数；这个可以跨线程。\nlet menu = ___::new(vec!["bun", "egg tart"]);\nlet m2 = menu.clone();\nthread::spawn(move || println!("{}", m2[0]));\n',
  ['// Same bound, written under the signature for long lists.\nfn show_all<T>(items: &[T])\n___\n    T: std::fmt::Display,\n{\n    for it in items { println!("{it}"); }\n}\n'] = '// 同样的约束，列表长时写在签名下面。\nfn show_all<T>(items: &[T])\n___\n    T: std::fmt::Display,\n{\n    for it in items { println!("{it}"); }\n}\n',
  ["// Take any Cook at all; the caller picks the concrete type.\nfn fire(c: ___ Cook) -> String {\n    c.greet()\n}\n"] = "// 接收任何 Cook；具体类型由调用方决定。\nfn fire(c: ___ Cook) -> String {\n    c.greet()\n}\n",
  ['// The banner is baked into the binary for the whole run.\nfn banner() -> &___ str {\n    "Lucky Mac Express"\n}\n'] = '// 横幅烧进了二进制文件，整个运行期都在。\nfn banner() -> &___ str {\n    "Lucky Mac Express"\n}\n',
  ["// The child lives on the heap, behind a pointer.\ntype Link = Option<___<Node>>;\nstruct Node {\n    val: i32,\n    left: Link,\n    right: Link,\n}\n"] = "// 子节点住在堆上，藏在一个指针后面。\ntype Link = Option<___<Node>>;\nstruct Node {\n    val: i32,\n    left: Link,\n    right: Link,\n}\n",
  ['// The entry point of a binary crate.\nfn ___() {\n    println!("Lucky Mac Express");\n}\n'] = '// 二进制 crate 的入口点。\nfn ___() {\n    println!("Lucky Mac Express");\n}\n',
  ["// The first line of a Go file.\npackage ___\nfunc hello() {}\n"] = "// Go 文件的第一行。\npackage ___\nfunc hello() {}\n",
  ['// The pass holds three trays: send blocks when full.\nlet (tx, rx) = mpsc::___(3);\ntx.send("tray").unwrap();\n'] = '// 出餐口放得下三个托盘：满了 send 就阻塞。\nlet (tx, rx) = mpsc::___(3);\ntx.send("tray").unwrap();\n',
  ["// The receipt only borrows the name: say so on the struct.\nstruct Receipt___ {\n    name: &'a str,\n    total: u32,\n}\n"] = "// 收据只是借用名字：在 struct 上说明。\nstruct Receipt___ {\n    name: &'a str,\n    total: u32,\n}\n",
  ["// The tea thread hands back a number when it is done.\nlet tea = thread::spawn(|| 3 * 60);\n// Wait for it and take the result out of the handle.\nlet secs: u32 = tea.___().unwrap();\n"] = "// 泡茶线程完成时交回一个数字。\nlet tea = thread::spawn(|| 3 * 60);\n// 等它结束，从句柄里取出结果。\nlet secs: u32 = tea.___().unwrap();\n",
  ['// The till gives change back, or a message.\nfn pay(cash: u32, price: u32) -> ___<u32, String> {\n    if cash < price {\n        return Err("not enough cash".to_string());\n    }\n    Ok(cash - price)\n}\n'] = '// 收银机找零，或者给一条消息。\nfn pay(cash: u32, price: u32) -> ___<u32, String> {\n    if cash < price {\n        return Err("not enough cash".to_string());\n    }\n    Ok(cash - price)\n}\n',
  ["// Two buns from one tray: the winner lives as long as both.\nfn longest<'a>(a: &'a str, b: &'a str) -> &___ str {\n    if a.len() >= b.len() { a } else { b }\n}\n"] = "// 同一托盘的两个包：胜者活得和两者一样久。\nfn longest<'a>(a: &'a str, b: &'a str) -> &___ str {\n    if a.len() >= b.len() { a } else { b }\n}\n",
  ["// ___ menu prices the morning set and the tea set.\npackage menu\n"] = "// ___ menu prices the morning set and the tea set.\npackage menu\n",
  ['// a literal is a &str; the kiosk needs its own copy\nlet shop = String::___("Lucky Mac Express");\nlet label: &str = &shop;\n'] = '// 字面量是 &str；自助机需要自己的一份拷贝\nlet shop = String::___("Lucky Mac Express");\nlet label: &str = &shop;\n',
  ['// a max-heap of (count, word), built straight from the map\nlet mut heap: BinaryHeap<(usize, &str)> =\n    cnt.into_iter().map(|(w, c)| (c, w)).___();\n// k pops: most frequent first, tuples compare by count\nfor _ in 0..k {\n    if let Some((c, w)) = heap.pop() { print!("{w} "); }\n}\n'] = '// (count, word) 的最大堆，直接从 map 构建\nlet mut heap: BinaryHeap<(usize, &str)> =\n    cnt.into_iter().map(|(w, c)| (c, w)).___();\n// pop k 次：最高频的先出，元组按 count 比较\nfor _ in 0..k {\n    if let Some((c, w)) = heap.pop() { print!("{w} "); }\n}\n',
  ["// a second stack: the smallest so far, at every depth\nfn push(&mut self, x: i32) {\n    let m = *self.low.last().unwrap_or(&x);\n    self.st.push(x);\n    self.low.push(x.___(m));\n}\n// the smallest: *self.low.last().unwrap()   O(1)\n"] = "// 第二个栈：每层深度上目前的最小值\nfn push(&mut self, x: i32) {\n    let m = *self.low.last().unwrap_or(&x);\n    self.st.push(x);\n    self.low.push(x.___(m));\n}\n// 最小值：*self.low.last().unwrap()   O(1)\n",
  ["// b'a' is the byte 97. Subtracting it maps a..z onto 0..26.\n// An array index must be the pointer-sized unsigned type.\nlet mut count = [0i32; 26];\nfor c in \"muffin\".bytes() {\n    count[(c - b'a') as ___] += 1;\n}\n"] = "// b'a' 是字节 97。减掉它，a..z 就映射到 0..26。\n// 数组下标必须是指针大小的无符号类型。\nlet mut count = [0i32; 26];\nfor c in \"muffin\".bytes() {\n    count[(c - b'a') as ___] += 1;\n}\n",
  ["// biggest run of days: extend the run, or start over at x\nlet (mut cur, mut best) = (a[0], a[0]);\nfor &x in &a[1..] {\n    cur = x.___(cur + x);\n    if cur > best { best = cur; }\n}\n"] = "// 最赚的一段：延续它，或从 x 重新开始\nlet (mut cur, mut best) = (a[0], a[0]);\nfor &x in &a[1..] {\n    cur = x.___(cur + x);\n    if cur > best { best = cur; }\n}\n",
  ["// binary_search on an unsorted slice returns nonsense.\n// Precondition: a is ___ ascending.\na.sort();\nlet i = a.binary_search(&38);\n"] = "// 对未排序切片做 binary_search 会返回胡话。\n// 前提：a 是升序 ___。\na.sort();\nlet i = a.binary_search(&38);\n",
  ['// both futures make progress on this task at once\nlet (a, b) = tokio::___!(fetch_eta(1), fetch_eta(2));\nprintln!("rider A {a} min, rider B {b} min");\n'] = '// 两个 future 在这个任务上同时推进\nlet (a, b) = tokio::___!(fetch_eta(1), fetch_eta(2));\nprintln!("rider A {a} min, rider B {b} min");\n',
  ["// calling this does nothing yet; it hands back a Future\n___ fn fetch_eta(order_id: u32) -> u32 {\n    tokio::time::sleep(Duration::from_millis(200)).await;\n    order_id % 10 + 5\n}\n"] = "// 调用它什么都还不会发生；它只交回一个 Future\n___ fn fetch_eta(order_id: u32) -> u32 {\n    tokio::time::sleep(Duration::from_millis(200)).await;\n    order_id % 10 + 5\n}\n",
  ["// cmd/kiosk/main.go\npackage ___\n\nfunc main() { kiosk.Run() }\n"] = "// cmd/kiosk/main.go\npackage ___\n\nfunc main() { kiosk.Run() }\n",
  ["// count every dish name once per receipt\nlet mut cnt: HashMap<&str, usize> = HashMap::new();\nfor w in words {\n    *cnt.___(w).or_insert(0) += 1;\n}\n"] = "// 每张收据上的每个菜名计一次数\nlet mut cnt: HashMap<&str, usize> = HashMap::new();\nfor w in words {\n    *cnt.___(w).or_insert(0) += 1;\n}\n",
  ["// dp[a] = fewest coins that make amount a\nfor a := range dp {\n    dp[a] = ___             // 'impossible' until proven\n}\ndp[0] = 0\n"] = "// dp[a] = 凑出金额 a 的最少硬币数\nfor a := range dp {\n    dp[a] = ___             // 证明之前都算“不可能”\n}\ndp[0] = 0\n",
  ["// first parameter, never a struct field\nfunc Cook(___ context.Context, o Order) error {\n    return nil\n}\n"] = "// 永远是第一个参数，不放进 struct\nfunc Cook(___ context.Context, o Order) error {\n    return nil\n}\n",
  ["// go f() starts a ___\n// thousands of them are cheap\n"] = "// go f() 启动一个 ___\n// 开几千个也很便宜\n",
  ["// k items left; the top is the smallest of the k biggest\nlet Reverse(kth) = *heap.___().unwrap();\nkth\n// kth_largest(&[3, 2, 1, 5, 6, 4], 2) == 5\n"] = "// 剩 k 个；堆顶是最大 k 个里最小的\nlet Reverse(kth) = *heap.___().unwrap();\nkth\n// kth_largest(&[3, 2, 1, 5, 6, 4], 2) == 5\n",
  ["// kth largest: a heap of the k biggest, smallest on top.\n// BinaryHeap is a max-heap; a std::cmp wrapper flips it.\nlet mut heap = BinaryHeap::new();\nfor &x in nums {\n    heap.push(___(x));\n    if heap.len() > k { heap.pop(); }\n}\n"] = "// 第 k 大：装着最大 k 个的堆，最小的在顶。\n// BinaryHeap 是最大堆；std::cmp 的包装翻转它。\nlet mut heap = BinaryHeap::new();\nfor &x in nums {\n    heap.push(___(x));\n    if heap.len() > k { heap.pop(); }\n}\n",
  ["// level 1: merge 2 halves      -> n items moved\n// level 2: merge 4 quarters    -> n items moved\n// each level: ___ ; levels: log n ; total: n log n\n"] = "// 第 1 层：合并 2 个一半      -> 移动 n 项\n// 第 2 层：合并 4 个四分之一  -> 移动 n 项\n// 每层：___ ；层数：log n ；总计：n log n\n",
  ['// main.go, module github.com/alex/luckymac\nimport "___"\n\nfmt.Println(menu.Price("set"))\n'] = '// main.go, module github.com/alex/luckymac\nimport "___"\n\nfmt.Println(menu.Price("set"))\n',
  ["// menu/price.go\npackage ___\n\nfunc price(item string) int { return 42 }\n"] = "// menu/price.go\npackage ___\n\nfunc price(item string) int { return 42 }\n",
  ["// menu/price.go\npackage menu\n\nfunc ___(item string) int { return 42 }\n"] = "// menu/price.go\npackage menu\n\nfunc ___(item string) int { return 42 }\n",
  ['// menu/price_test.go\npackage menu___\n\nimport "github.com/alex/luckymac/menu"\n'] = '// menu/price_test.go\npackage menu___\n\nimport "github.com/alex/luckymac/menu"\n',
  ["// merge(l, r): both slices are already sorted\nlet (mut i, mut j, mut out) = (0, 0, Vec::new());\nwhile i < l.len() && j < r.len() {\n    if l[i] ___ r[j] { out.push(l[i]); i += 1; }\n    else { out.push(r[j]); j += 1; }\n}\nout.extend(&l[i..]); out.extend(&r[j..]);\n"] = "// merge(l, r)：两个切片都已经有序\nlet (mut i, mut j, mut out) = (0, 0, Vec::new());\nwhile i < l.len() && j < r.len() {\n    if l[i] ___ r[j] { out.push(l[i]); i += 1; }\n    else { out.push(r[j]); j += 1; }\n}\nout.extend(&l[i..]); out.extend(&r[j..]);\n",
  ["// n = 100\n// pairs = 100 * 99 / 2 = ___\n// still O(n^2): the /2 is a constant\n"] = "// n = 100\n// 对数 = 100 * 99 / 2 = ___\n// 仍然 O(n^2)：/2 是常数\n",
  ["// n = 1000 -> items[3] : 1 step\n// n = 2000 -> items[3] : 1 step\n// the cost stays the ___\n"] = "// n = 1000 -> items[3] : 1 步\n// n = 2000 -> items[3] : 1 步\n// 代价保持 the ___\n",
  ['// position gives an Option; the till wants a Result.\nfn find(menu: &[&str], w: &str) -> Result<usize, String> {\n    menu.iter()\n        .position(|m| *m == w)\n        .___("not on the menu".to_string())\n}\n'] = '// position 给的是 Option；收银机要 Result。\nfn find(menu: &[&str], w: &str) -> Result<usize, String> {\n    menu.iter()\n        .position(|m| *m == w)\n        .___("not on the menu".to_string())\n}\n',
  ["// quicksort halves the range each level on average\n// depth ~ log2(n) frames on the stack: O(___) space\n// (naive fib without memo: depth n)\n"] = "// 快速排序平均每层把范围减半\n// 深度 ~ 栈上 log2(n) 个帧：O(___) 空间\n// （没有 memo 的朴素 fib：深度 n）\n",
  ["// returns a JoinHandle; the task runs on the pool now\nlet handle = tokio::___(async { fetch_eta(3).await });\nprint_menu().await;\nlet eta = handle.await?;\n"] = "// 返回 JoinHandle；任务现在已在线程池上跑了\nlet handle = tokio::___(async { fetch_eta(3).await });\nprint_menu().await;\nlet eta = handle.await?;\n",
  ["// starts a line comment. /// is a doc comment that cargo doc turns into pages."] = "// 开始一条行注释。/// 是文档注释，cargo doc 会把它变成网页。",
  ["// the caller only learns: it is some Iterator of &str\nfn free_riders() -> ___ Iterator<Item = &'static str> {\n    [\"Wing\", \"Fai\"].into_iter().filter(|r| *r != \"Fai\")\n}\n"] = "// 调用方只知道：这是某个产出 &str 的 Iterator\nfn free_riders() -> ___ Iterator<Item = &'static str> {\n    [\"Wing\", \"Fai\"].into_iter().filter(|r| *r != \"Fai\")\n}\n",
  ['// the mall has five floors of pickup lockers\nfor floor in 1___5 {\n    println!("checking locker on floor {floor}");\n}\n// prints 1, 2, 3, 4, 5\n'] = '// 商场有五层取餐柜\nfor floor in 1___5 {\n    println!("checking locker on floor {floor}");\n}\n// 打印 1, 2, 3, 4, 5\n',
  ["// the sum of every window of k, without re-adding k items\nlet mut sum: i32 = a[..k].iter().sum();\nlet mut best = sum;\nfor i in k..a.len() {\n    sum += a[i] - a[___];       // one in, one out\n    if sum > best { best = sum; }\n}\n"] = "// 每个 k 窗口的和，不必重新加 k 个元素\nlet mut sum: i32 = a[..k].iter().sum();\nlet mut best = sum;\nfor i in k..a.len() {\n    sum += a[i] - a[___];       // 一进一出\n    if sum > best { best = sum; }\n}\n",
  ['// three characters, three bytes each in UTF-8\nlet district = "銅鑼灣";\nlet n = district.___();\nassert_eq!(n, 9);\n'] = '// 三个字符，UTF-8 里每个占三字节\nlet district = "銅鑼灣";\nlet n = district.___();\nassert_eq!(n, 9);\n',
  ["// two_sum: value -> index in a HashMap, one pass, O(n)\nlet mut seen = HashMap::new();\nfor (i, &x) in nums.iter().enumerate() {\n    let want = target - x;\n    if seen.___(&want) { return Some((seen[&want], i)); }\n    seen.insert(x, i);\n}\n"] = "// two_sum：HashMap 里存 值 -> 下标，一趟搞定，O(n)\nlet mut seen = HashMap::new();\nfor (i, &x) in nums.iter().enumerate() {\n    let want = target - x;\n    if seen.___(&want) { return Some((seen[&want], i)); }\n    seen.insert(x, i);\n}\n",
  ["// without memo: 2^n calls\n// with memo: fib(0) .. fib(n), each once -> O(___)\n"] = "// 没有 memo：2^n 次调用\n// 有 memo：fib(0) .. fib(n)，每个一次 -> O(___)\n",
  ["// worker(id, rx): the let drops the lock guard at the\n// semicolon, so the job runs with the rail unlocked.\nloop {\n    let msg = rx.lock().unwrap().___();\n    let Ok(job) = msg else { break };  // Err: senders gone\n    job();\n}\n"] = "// worker(id, rx)：这个 let 在分号处就丢掉了锁 guard，\n// 所以任务运行时这条轨是没锁的。\nloop {\n    let msg = rx.lock().unwrap().___();\n    let Ok(job) = msg else { break };  // Err：发送者都没了\n    job();\n}\n",
  ["//go:embed puts files in the binary: string, []byte or embed.FS."] = "//go:embed 把文件放进二进制：string、[]byte 或 embed.FS。",
  ["0  PNG DISK"] = "0  PNG 磁盘",
  ["0 is clean, a positive number is sys.exit(n), and a negative one is the signal that killed it: -9 is the out-of-memory killer."] = "0 表示干净退出，正数是 sys.exit(n)，负数是杀死它的那个信号：-9 就是内存不足杀手。",
  ["0..3 stops before 3. Which range operator includes the last number?"] = "0..3 在 3 之前停下。哪个范围运算符包含最后一个数？",
  ["00:00. CODE RUSH, the live coding show on the Times Square screen, midnight edition: Python. The night market crowd, a buzzer, seven rounds, Chef Bo at the keyboard. No misses keeps the combo. Round one: recursion, and why fib needs a memo."] = "00:00。CODE RUSH，时代广场大屏幕上的直播编程秀，午夜场：Python。夜市的观众、蜂鸣器、七个回合，Bo 厨师坐在键盘前。不失误就保持连击。第一回合：递归，以及 fib 为什么需要 memo。",
  ["01:00. The night market is packing up and the startup's back office is still lit. Siu Ming, host by night, interviewer by later night, hands Chef Bo a marker. The Times Square screen said HIRED; the whiteboard decides the offer. Round one: a receipt full of brackets. Are they balanced?"] = "01:00。夜市在收摊，创业公司的后勤室还亮着灯。小明，夜里是主持人，更深的夜里是面试官，把一支马克笔递给 Bo 厨师。时代广场的大屏说了 HIRED；白板决定 OFFER。第一回合：一张满是括号的收据。它们配对了吗？",
  ["02:00. The shutters are down and the night batch has forty thousand photos to resize before the morning delivery. Chef Bo threw threads at it and the laptop got hot and no faster. One lock in the interpreter is why, and there is exactly one way around it."] = "02:00。卷帘门拉下来了，夜间批处理要在早上送货之前缩掉四万张照片。宝厨往上面丢了一堆线程，笔记本发烫，却一点没变快。原因是解释器里的那把锁，而绕开它的路恰好只有一条。",
  ["02:15. The fix looks like one word: Thread becomes Process. Then the terminal fills with the same log line a hundred times over, because a spawned child imports the script it came from and runs everything that is not tucked behind the main guard."] = "02:15。看上去只要改一个词：Thread 变成 Process。然后终端被同一行日志刷了上百遍，因为 spawn 出来的子进程会 import 它自己那个脚本，并运行所有没有收在 main guard 后面的东西。",
  ["02:30. Forty thousand photos, eight cores, and one lesson: pay for the interpreters once. A Pool is eight cooks reading the same order book, and the only real decision left is how many photos each of them carries across the kitchen at a time."] = "02:30。四万张照片、八个核，以及一个教训：解释器的钱只付一次。一个 Pool 就是八个厨师读同一本落单簿，剩下的唯一真正决定，是他们每次端着几张照片穿过厨房。",
  ["02:45. The receipts worker fills a list and the parent prints nothing, over and over. There is no bug: the child got a copy of the list at start-up and has been filling that. Between processes there is only the dumbwaiter, and everything on it is pickled."] = "02:45。单据 worker 在填一个列表，父进程却什么都印不出来，一遍又一遍。这不是 bug：子进程在启动时拿到了这个列表的副本，一直在填那个。进程之间只有那台升降机，上面的一切都被 pickle 过。",
  ["03:00. Eight workers, one label printer, and a sticker with two orders printed on top of each other. Separate memory did not make the printer separate. What crosses process lines now is not data but permission: who may write, and when."] = "03:00。八个 worker、一台标签打印机，还有一张把两张订单印在一起的贴纸。内存分开并没有让打印机也分开。现在越过进程边界的不是数据，而是许可：谁可以写，什么时候写。",
  ["03:20. The month's receipts are two gigabytes and every worker got its own pickled copy of them: eight copies, eight seconds of pickling, one machine on its knees. The cold room is the answer. One block of bytes, everybody walks in, nobody carries it."] = "03:20。这个月的单据有两个 GB，而每个 worker 都拿到了自己那份 pickle 副本：八份副本、八秒 pickle、一台跪下的机器。冷藏室就是答案。一块字节，人人走进去，没人搬着走。",
  ["03:50. The van comes at five. What is left is four hundred HTTP calls to the supplier and four hundred images to resize, and Chef Bo wants one way to write both. concurrent.futures is that way: the same six lines, and one word that decides whether it waits or computes."] = "03:50。货车五点来。剩下的是四百个给供应商的 HTTP 调用和四百张要缩的图，而宝厨想用一种写法搞定两样。concurrent.futures 就是那种写法：同样的六行，加上一个决定它是等还是算的词。",
  ["06:40. Causeway Bay. Alex wants a muffin, a hash brown and coffee. The flat's door kiosk will not unlock until the Go file compiles."] = "06:40，铜锣湾。Alex 想要松饼、薯饼和咖啡。Go 文件编译通过之前，公寓门口的自助机不会开锁。",
  ["08:10. Breakfast done. The owner wants a delivery app before the lunch rush. First ticket: the signboard shows 銅鑼灣 wrong, because a Go string is bytes, not characters."] = "08:10。早餐吃完了。老板想在午市高峰前上线一个外卖 app。第一张工单：招牌上的 銅鑼灣 显示不对，因为 Go 的 string 是字节，不是字符。",
  ["1  QUESTION"] = "1  问题",
  ["1 + max(hl, hr). A balanced tree of n nodes is about log2(n) tall; a sorted insert order makes a list, height n."] = "1 + max(hl, hr)。n 个节点的平衡树大约 log2(n) 高；按排好的顺序插入会变成链表，高度 n。",
  ["1-4 copy    5-0 export    A all    S scope    ESC close"] = "1-4 复制    5-0 导出    A 全部    S 范围    ESC 关闭",
  ["1-7 jump straight in.   Q quest.   TAB Go/Rust.   F3 language.   F4 sound.   ESC quit."] = "1-7 直接跳入。   Q 任务。   TAB Go/Rust。   F3 语言。   F4 声音。   ESC 退出。",
  ["1-7 jump straight in.   Q quest.   TAB Go/Rust/Python.   F3 language.   F4 sound.   ESC quit."] = "1-7 直接跳入。   Q 任务。   TAB Go/Rust/Python。   F3 语言。   F4 声音。   ESC 退出。",
  ["1..=3 is 1, 2, 3. for in Rust walks anything iterable: ranges, Vec, iterators."] = "1..=3 是 1、2、3。Rust 的 for 能遍历任何可迭代的东西：范围、Vec、迭代器。",
  ['1..=5 is RangeInclusive; 1..5 stops at 4. Also in patterns: 1..=5 => "low".'] = '1..=5 是 RangeInclusive；1..5 到 4 就停。模式里也能用：1..=5 => "low"。',
  ["10. A million items take 20, a billion 30. That is how slowly log n grows."] = "10。一百万项要 20，十亿要 30。log n 就长得这么慢。",
  ["10. A million items take 20, a billion 30. That is how slowly log n grows: the line almost lies down."] = "10。一百万项要 20，十亿要 30。log n 就长得这么慢：线几乎躺平。",
  ["100 RIGHT"] = "答对 100 题",
  ["1024 sorted items. Halving each time, at most how many steps until one is left?"] = "1024 个有序项。每次减半，最多几步剩下一个？",
  ["12:00. Both tills are open, the queue is out to Percival Street, and the counter on the wall is wrong by six. Nobody stole anything: sold++ is a read, an add and a write, and two goroutines read the same number before either wrote it back."] = "12:00。两台收银机都开着，队伍排到波斯富街，墙上的计数少了六。没人偷东西：sold++ 是一次读、一次加、一次写，两个 goroutine 在对方写回之前读到了同一个数。",
  ["12:20. The door sensor, the till and the delivery app all raise one counter. A mutex would work and would also be the slowest thing in the building. The hardware can add without a lock; the sync/atomic package is how Go asks it to."] = "12:20。门口传感器、收银机和外卖 App 都在加同一个计数。用 mutex 也行，但那会成为整栋楼里最慢的东西。硬件本来就能不加锁地做加法；sync/atomic 包就是 Go 请它这么做的方式。",
  ["12:35. The kitchen board is a map[string]int the six wok goroutines all write to, and Go kills the process for it on purpose: a torn map is worse than a stopped one. Alex has three ways out, and only one of them is a lock."] = "12:35。厨房那块板是一个 map[string]int，六个炒锅 goroutine 都在写它，而 Go 是故意把进程杀掉的：一个撕裂的 map 比一个停下的程序更糟。阿力有三条出路，其中只有一条是锁。",
  ["12:50. Forty riders, eight bikes, one printer. Goroutines are cheap enough that Alex made one per order and the queue turned to noise. A pool is the fix: a fixed number of workers, all reading the same channel, all finishing before the shift ends."] = "12:50。四十个骑手、八辆单车、一台打印机。goroutine 便宜到阿力给每张订单开了一个，于是队列变成了噪音。修法是池子：固定数量的 worker，都读同一条 channel，都在下班前做完。",
  ["13:00. CODE RUSH, the live coding show on the Times Square screen. A crowd, a buzzer, seven rounds. Answer without a miss to keep the combo. Round one: recursion, and why fib needs a memo."] = "13:00。CODE RUSH，时代广场大屏上的编程直播秀。人群、抢答器、七个回合。一题不错才能保住连击。第一回合：递归，以及 fib 为什么需要 memo。",
  ["13:05. The kitchen stopped sending but the counter kept receiving, and every receive came back instantly with an empty Order. A closed channel is not an error: it is a promise that nothing more is coming, and the second value of the receive is where it says so."] = "13:05。厨房停止发送了，柜台还在接收，而每次接收都立刻返回一张空 Order。关闭的 channel 不是错误：它是「没有更多东西要来了」的承诺，而接收的第二个值就是它说这句话的地方。",
  ["13:20. A rider cancels, the customer closes the app, and three goroutines carry on fetching an ETA nobody will read. Go cannot kill a goroutine from outside: cancellation is a value you pass in and a channel the work agrees to watch."] = "13:20。骑手取消了，客人关掉了 App，而三个 goroutine 还在取一个没人会看的 ETA。Go 无法从外面杀死一个 goroutine：取消是你传进去的一个值，以及一条工作答应会盯着的 channel。",
  ["13:40. Alex asks the question every newcomer asks: where is async, where is await? Mei draws two lines on the whiteboard. Start it with go. Wait for it with an arrow. Everything async/await gives you, Go gives you without splitting functions into two kinds."] = "13:40。阿力问了每个新手都会问的问题：async 在哪里，await 在哪里？阿美在白板上画了两行。用 go 启动它。用一个箭头等它。async/await 给你的一切，Go 都给你，而且不用把函数分成两种。",
  ["14:30. The screen at Times Square still says HIRED, but the startup wants a second round in the back office: a whiteboard, a marker, Siu Ming with a list. Round one is the question every callback starts with: does every bracket close in the right order?"] = "14:30。时代广场的大屏还写着 HIRED，但这家创业公司想在后勤室再来一轮：一块白板、一支马克笔，小明拿着一份题单。第一回合是每次复试都从它开始的问题：每个括号都按正确顺序闭合了吗？",
  ["15:00. Lunch is done at Lucky Mac. Mei's laptop shows the Times Square branch: every kiosk of Lucky Mac Express is frozen on a Rust file with no main. Alex knows Go. Mei knows Rust. They start walking."] = "15:00。Lucky Mac 的午饭吃完了。Mei 的笔记本显示时代广场分店：幸运麦 Express 的每台自助机都卡在一个没有 main 的 Rust 文件上。Alex 会 Go。Mei 会 Rust。他们动身出发。",
  ["15:08. The tram stop on Percival Street. The next-tram sign runs a tiny Rust program and it will not compile: someone tried to change a value that was never marked mut. Mei fixes it while Alex reads the error messages out loud."] = "15:08。波斯富街的电车站。下一班电车的指示牌跑着一个小 Rust 程序，却编译不过：有人想改一个从没标 mut 的值。Mei 动手修，Alex 大声念错误信息。",
  ["15:15. The underpass at Causeway Bay MTR exit A. The Lucky Mac Express ad gate should show muffin, coffee or set as people walk past, but its match has a hole and the loop never ends. Mei counts the cases on her fingers."] = "15:15。铜锣湾地铁 A 出口的地下通道。幸运麦 Express 的广告门应该在人经过时显示松饼、咖啡或套餐，可它的 match 有个漏洞，循环也停不下来。Mei 掰着手指数情况。",
  ["15:20. The footbridge over Canal Road, Times Square's clock ahead. The Express delivery board on the bridge shows the price of every set, but the pricing function returns nothing and the seat finder crashes on an empty table. Alex tries the Rust himself for the first time."] = "15:20。跨过坚拿道的天桥，前方是时代广场的大钟。桥上的 Express 外卖板显示每份套餐的价格，可定价函数什么都不返回，找座位的功能遇到空桌就崩。Alex 第一次自己动手写 Rust。",
  ["15:25. The atrium of Times Square, the crab sticker on the Express order kiosk. The kiosk prints a receipt, then tries to read the same String again and the compiler says: value used after move. Mei explains who owns the tray."] = "15:25。时代广场中庭，Express 点餐机上贴着螃蟹贴纸。点餐机打印收据，然后想再读同一个 String，编译器说：value used after move。Mei 解释托盘归谁。",
  ["15:30. The delivery app is one file and the Times Square shop wants to import the menu code from GitHub. Before there is a package to import there has to be a module to hold it, and the module's name is not a label: it is the first half of every import path."] = "15:30。外卖 App 只有一个文件，而时代广场那家店想从 GitHub 导入菜单代码。在有包可导入之前，得先有一个模块来装它，而模块的名字不是标签：它是每条导入路径的前半截。",
  ["15:30. The queue outside Lucky Mac Express, twelve people and a crab sticker on the board. The board should list every order's price and count the muffins per table, but the Vec is never pushed to and the HashMap panics on a missing key. Siu Ming waves them to the front."] = "15:30。幸运麦 Express 门外的队伍，十二个人，看板上一张螃蟹贴纸。看板应该列出每个订单的价格并按桌统计松饼，可 Vec 从没被 push 过，HashMap 一遇到不存在的键就 panic。小明挥手叫他们到前面来。",
  ["15:35. The counter of Lucky Mac Express at last, the crab sticker smiling on the till. The till keeps orders as loose tuples and cannot print them, and a size of Medium sneaks in that the kitchen does not know. Siu Ming needs an Order type before the afternoon set can be sold."] = "15:35。终于到了幸运麦 Express 的柜台，收银机上的螃蟹贴纸在笑。收银机用零散的元组存订单，打印不出来，还混进一个厨房不认识的 Medium 尺寸。小明需要一个 Order 类型，下午茶套餐才能卖。",
  ["15:45. The menu code moves into its own folder and immediately breaks in three ways: the package is named after nothing, main cannot see the price function, and the import written as ./menu will not build. All three are the same lesson about what a path means."] = "15:45。菜单代码搬进自己的文件夹，立刻坏了三处：包名什么都不像，main 看不见 price 函数，写成 ./menu 的 import 编译不过。三处都是同一课：一条路径到底意味着什么。",
  ["16:00. Lucky Mac Express, Times Square. The till took a coin it could not parse and froze on a red Err. Siu Ming has a queue; Alex has to learn how Rust hands errors back."] = "16:00。幸运麦 Express，时代广场。收银机收了一枚解析不了的硬币，卡在红色的 Err 上。小明那边排着队；Alex 得学会 Rust 怎么把错误交回来。",
  ["16:00. The cousin's shop imports github.com/alex/luckymac/menu and the go tool fetches it from GitHub without being told where GitHub is: the host is in the path. What it writes down afterwards, in go.mod and go.sum, is what makes next month's build the same build."] = "16:00。表哥的店导入 github.com/alex/luckymac/menu，go 工具没人告诉它 GitHub 在哪就从 GitHub 取来了：主机就在路径里。它之后写进 go.mod 和 go.sum 的东西，就是让下个月的构建还是同一个构建的原因。",
  ["16:10. The Express kitchen. Chef Bo's pass runs every station through one Rust program, but the grill and the wok speak different types and the order board shows nothing. A trait gives them one shared voice."] = "16:10。Express 的厨房。波师傅的出餐口用一个 Rust 程序管所有工位，可烤架和炒锅说的是不同的类型，订单板什么都不显示。一个 trait 给它们一个共同的声音。",
  ["16:15. Exporting a name is a promise, and the cousin's shop just took Alex up on one he never meant to make. The fix is not a comment asking people to be nice: it is a directory name the compiler enforces, and a layout that says which packages are the API."] = "16:15。导出一个名字就是一个承诺，而表哥的店刚刚接受了一个阿力从没打算许下的承诺。修法不是写条注释请大家客气点：而是一个由编译器强制的目录名，以及一套说明哪些包是 API 的布局。",
  ["16:20. The kiosk in the mall corridor has one price list in u32 and one weight list in f64, and two copies of every function. The crab on the screen sulks. Generics fold them into one."] = "16:20。商场走廊的自助机有一份 u32 的价格表和一份 f64 的重量表，每个函数都写了两遍。屏幕上的螃蟹在生气。泛型把它们合成一个。",
  ["16:30. The path problem in the flesh: the library on disk is newer than the library in the cache, and the import path points at the cache. Two lines of go.mod, or one go.work file, redirect a path to a folder while you work, and tidy puts go.mod back in step."] = "16:30。路径问题的真身：磁盘上的库比缓存里的新，而导入路径指向缓存。go.mod 里的两行，或者一个 go.work 文件，在你干活期间把路径转向文件夹，tidy 再让 go.mod 重新对齐。",
  ["16:30. The set table by the window. The receipt printer holds a reference to a name that was freed one line earlier and Rust refuses to build. Alex learns to say how long a borrow lives."] = "16:30。窗边的套餐桌。收据打印机持有一个名字的引用，而那个名字在前一行就被释放了，Rust 拒绝编译。Alex 学着说出一次借用能活多久。",
  ["16:40. Three orders, one cook, one thread: the pineapple buns wait while the kettle boils. Chef Bo wants the grill, the kettle and the pass to run at the same time. Rust threads are real OS threads; no go keyword here."] = "16:40。三个订单，一个厨师，一个线程：水壶烧着，菠萝包只能等。波师傅想让烤架、水壶和出餐口同时干活。Rust 的线程是真正的操作系统线程；这里没有 go 关键字。",
  ["16:45. There is no publish button. A Go module is released by pushing a git tag, and the number on the tag is a contract: patch and minor never break a caller, and a major that does gets a new import path so old and new can live side by side."] = "16:45。没有发布按钮。Go 模块靠推送一个 git 标签来发布，而标签上的数字是一份契约：patch 和 minor 永远不破坏调用者，会破坏的 major 拿到新的导入路径，新旧可以并存。",
  ["16:50. Two tills at Lucky Mac Express and one kitchen. Orders sit in a shared Vec that both tills scribble on and the kitchen never sees. Mei replaces the Vec with a channel: many senders, one receiver."] = "16:50。幸运麦 Express 两台收银机，一个厨房。订单堆在一个共享 Vec 里，两台收银机乱写，厨房却从没看到。Mei 用 channel 换掉 Vec：多个发送者，一个接收者。",
  ["17:00. Last hour before the tea set. Both tills bump one sold counter from two threads and the total drifts. Rc will not even compile across threads; Mei reaches for Arc, Mutex and one atomic. Get it right and the afternoon tea set is yours."] = "17:00。下午茶套餐前的最后一小时。两台收银机从两个线程给同一个销量计数器加一，总数却对不上。Rc 跨线程连编译都过不了；Mei 拿出 Arc、Mutex 和一个原子类型。做对了，下午茶套餐就是你的。",
  ["17:00. Lucky Mac Express, Times Square. The receipt printer writes the shop name as 銅鑼 and a broken square. Someone sliced a String by byte count. Mei opens ticket one."] = "17:00。幸运麦 Express，时代广场。收据打印机把店名打成了 銅鑼 加一个残缺的方块。有人按字节数切了 String。Mei 打开第一张工单。",
  ["17:00. The last path problem is not on disk: it is between the go tool, a public proxy that mirrors the whole ecosystem, and a repo that only Alex's ssh key can open. Two environment variables and one git setting route the private path around the proxy."] = "17:00。最后一个路径问题不在磁盘上：它在 go 工具、一个镜像了整个生态的公开代理，和一个只有阿力的 ssh 密钥能打开的仓库之间。两个环境变量和一条 git 设置，把私有路径绕过代理。",
  ["17:10. The till at Lucky Mac Express unwraps every parse. One bad keypad entry and the drawer prints a stack trace instead of a receipt. Siu Ming wants a real error type."] = "17:10。幸运麦 Express 的收银机对每个 parse 都 unwrap。键盘输错一次，钱箱打出的不是收据而是堆栈跟踪。小明想要一个真正的错误类型。",
  ["17:20. The kitchen printer at Lucky Mac Express runs a hand-written index loop. It skips the first dish and prints the last one twice. Chef Bo hands Alex ticket three: iterators."] = "17:20。幸运麦 Express 的厨房打印机跑着一个手写的下标循环。它跳过第一道菜，最后一道打两次。波师傅把第三张工单交给 Alex：迭代器。",
  ['17:30. Under the mall atrium screens, the rider app and the kitchen disagree on field names, and every order arrives as "name": null. Ticket four: teach the structs to speak JSON with serde.'] = '17:30。商场中庭大屏下，骑手 app 和厨房在字段名上吵翻了，每个订单送到都是 "name": null。第四张工单：用 serde 教 struct 说 JSON。',
  ["17:40. Russell Street. Riders idle by the tram stop while the delivery backend fetches ETAs one by one, blocking on each. Ticket five: make the calls async and run them together on tokio."] = "17:40。罗素街。骑手们在电车站旁发呆，外卖后端却在一个一个地取 ETA，每次都阻塞。第五张工单：把调用改成 async，放到 tokio 上一起跑。",
  ["17:50. The pickup queue at Lucky Mac Express is out the door and the new backend is still a folder of .rs files. Alex has go build in his fingers. Mei: in Rust it is all cargo."] = "17:50。幸运麦 Express 的取餐队伍排到了门外，新后端还只是一个装满 .rs 文件的文件夹。Alex 手指记得的是 go build。Mei：在 Rust 里全靠 cargo。",
  ["17:55. Lucky Mac Express, the set counter. The backend compiles, but Mei's review has six comments: this is 2015 Rust. Alex rewrites each one the modern way. Then it ships. SHIPPED."] = "17:55。幸运麦 Express，套餐柜台。后端编译过了，但 Mei 的审查留了六条评论：这是 2015 年的 Rust。Alex 把每一处都改成现代写法。然后上线。已上线。",
  ["19:00. CODE RUSH, the live coding show on the Times Square screen, evening edition: Rust. A crowd, a buzzer, seven rounds, Mei at the keyboard. No misses keeps the combo. Round one: recursion, and why fib needs a memo."] = "19:00。CODE RUSH，时代广场大屏上的编程直播秀，夜场：Rust。人群、抢答器、七个回合，Mei 坐在键盘前。一题不错才能保住连击。第一回合：递归，以及 fib 为什么需要 memo。",
  ["19:08. Round two, and the screen shows a tree of order numbers. Insert, walk in order, measure the height. In Rust a tree is a struct with two Option<Box<Node>> fields, and the compiler wants to know its size."] = "19:08。第二回合，屏幕上是一棵订单号组成的树。插入、中序遍历、量高度。在 Rust 里，树是一个带两个 Option<Box<Node>> 字段的 struct，而编译器想知道它有多大。",
  ["19:17. Round three puts the MTR map on the big screen: stations are nodes, lines are edges. Mei has to reach every station once. Wide first with a queue, then deep with a stack, and a HashSet so nobody loops forever."] = "19:17。第三回合把港铁线路图搬上大屏：站是节点，线是边。Mei 要把每个站都走到一次。先用队列横着走，再用栈往深里走，还要一个 HashSet，免得有人一直绕圈。",
  ["19:26. Round four is the chain: a linked list of order tickets, out on the street where the delivery riders queue. Each node owns the next one. Reverse it, walk it, find the middle, and never touch a raw pointer."] = "19:26。第四回合是这条链：一串订单票组成的链表，就在骑手排队的那条街上。每个节点拥有下一个节点。把它反转、走一遍、找到中点，而且全程不碰裸指针。",
  ["19:35. Round five, the shuffle. The screen dumps a hundred order prices in random order. Mei writes merge sort from memory, then the host wants the std spelling: stable, unstable, and a binary search on the result."] = "19:35。第五回合，洗牌。屏幕上倒出一百个乱序的订单价格。Mei 凭记忆手写归并排序，然后主持人要她给出 std 的写法：稳定的、不稳定的，还有在结果上做一次二分查找。",
  ["19:44. Round six, the classics, back on the mall floor with the crowd pressing in. Two-sum, a palindrome, an anagram, a word count. Every one of them is a hash map or an array of 26, and every one is O(n)."] = "19:44。第六回合，经典题，回到商场大堂，人群围了上来。两数之和、回文、变位词、词频。每一题不是哈希表就是长度 26 的数组，而且每一题都是 O(n)。",
  ["19:55. The final, the one they always ask: N worker threads pull jobs from one channel. The Times Square screen shows the Lucky Mac Express kitchen as the diagram. Get the lock, the drop and the join right and the prize is HIRED."] = "19:55。最后一回合，他们总要问的那道题：N 个工作线程从同一条 channel 里取任务。时代广场的大屏把幸运麦 Express 的厨房画成了示意图。锁、drop 和 join 都做对，奖品就是 HIRED。",
  ["2  HINT"] = "2  提示",
  ["2 ** 10 is 1024. 2 ** 0.5 is a square root. Ints never overflow in Python; they just grow."] = "2 ** 10 是 1024。2 ** 0.5 是开平方。Python 的 int 永远不会溢出；只会越来越大。",
  ["20:30. The Times Square screen is dark; the startup's back office is not. A whiteboard, a marker, Siu Ming with a clipboard. The callback round: the problems the live show never had time for. First, brackets. Every ( wants its ), in order, and a Vec is the stack."] = "20:30。时代广场的大屏黑了；创业公司的后勤室没有。一块白板，一支马克笔，小明拿着写字板。回访轮：直播里没时间问的那些题。首先是括号。每个 ( 都要有它的 )，顺序不能乱，栈就是一个 Vec。",
  ["20:38. Siu Ming draws a staircase. One step or two at a time: how many ways to the top? Mei sees fib, but this time there is no memo: a Vec filled from the bottom. Then the till: the fewest coins for 27 dollars, from 1, 5 and 10. Same table, a min instead of a sum."] = "20:38。小明画了一段楼梯。一次一步或两步：到顶有多少种走法？Mei 看出是 fib，但这次没有 memo：一个从底向上填满的 Vec。然后是收银台：用 1、5、10 元凑 27 元最少要几枚硬币。同一张表，把求和换成取最小。",
  ["20:45. A week of Lucky Mac Express sales on the whiteboard, some days negative. Which run of days made the most? Mei writes Kadane in four lines. Then windows of k hours, then the longest stretch of dishes with no repeat. Every one of them is one pass and two indices."] = "20:45。白板上是幸运麦 Express 一周的销售额，有几天是负数。哪一段连续的日子赚得最多？Mei 四行写完 Kadane。然后是 k 小时的窗口，再是最长的不重复菜品序列。每一题都是一次遍历、两个下标。",
  ["20:52. Siu Ming dumps a box of receipts on the table: ten thousand of them. The third largest, please, and the five most ordered dishes. Sorting is O(n log n) and the crowd knows it. Mei draws a heap of size k on the board and the room goes quiet."] = "20:52。小明把一箱收据倒在桌上：一万张。请找出第三大的那张，还有点得最多的五道菜。排序是 O(n log n)，观众都知道。Mei 在板上画了一个大小为 k 的堆，全场安静下来。",
  ["21:00. The cook's shift sheet goes up on the board: a dozen (start, end) pairs, out of order, overlapping. When is the kitchen covered, and where are the gaps? Sort by start, keep the last merged shift in view, and each new one either stretches it or starts a fresh block."] = "21:00。厨师的排班表贴上了白板：十几对 (start, end)，乱序，还互相重叠。厨房什么时候有人，空档在哪里？按起点排序，盯住上一个合并后的班次，每个新班次要么把它拉长，要么另起一块。",
  ["21:00. The morning set is long gone and the Rust afternoon is over. Lucky Mac's night shift runs on Python scripts Chef Bo wrote years ago. Tonight the pass screen is blank. Bo hands Alex the laptop; a blue and yellow snake sticker on the lid seems to grin."] = "21:00。早餐套餐早已过去，Rust 的下午也结束了。幸运麦的夜班靠 Bo 厨师多年前写的 Python 脚本运转。今晚出餐口的屏幕是黑的。Bo 把笔记本交给 Alex；盖子上一只蓝黄色的蛇贴纸像在笑。",
  ["21:08. The one every backend interview ends with: a cache with a capacity, where the least recently used entry makes room for the new one. Mei keeps it honest: a HashMap for the values, a VecDeque for the order, and a note on the board that the linked-list version makes every step O(1)."] = "21:08。每场后端面试都以它收尾的那道题：有容量的缓存，最久未用的条目给新条目让位。Mei 老老实实地写：HashMap 存值，VecDeque 存顺序，再在板上注一句：链表版本能让每一步都 O(1)。",
  ["21:15. The last board: Victoria Harbour as a grid of ones and zeros. How many islands? Mei writes sink: stop at the edge, stop at water, turn this cell to water, flood the four neighbours. Count one per unsunk land cell. Siu Ming caps the marker. The screen outside lights up: OFFER."] = "21:15。最后一块板：维多利亚港画成一张 0 和 1 的网格。有几座岛？Mei 写 sink：出界就停，遇水就停，把这一格变成水，再洪泛四个邻居。每个还没沉的陆地格计一。小明盖上笔帽。外面的屏幕亮起：OFFER。",
  ["22:00. The back office behind the kitchen: a humming rack, two laptops, a whiteboard with a tree on it. The refund script crashes on the first bad receipt because nobody catches anything. Alex reaches for if err != nil; Bo shakes his head."] = "22:00。厨房后面的后勤室：嗡嗡响的机架、两台笔记本、一块画着树的白板。退款脚本遇到第一张坏收据就崩溃，因为没人捕获任何东西。Alex 伸手要写 if err != nil；Bo 摇头。",
  ["22:15. The shutter is half down and a small queue waits outside. Chef Bo's queue script counts bowls and people. It is missing every keyword that makes a decision. Mei reads Python like a recipe: colon, then indent."] = "22:15。卷帘门放下一半，外面等着一小队人。Bo 厨师的排队脚本数碗数人。所有做决定的关键字都不见了。Mei 读 Python 像读菜谱：冒号，然后缩进。",
  ["23:00. The last order robot at the market stall runs on a class called Order. Its constructor is gone, its methods lost their first parameter, and the receipt prints <__main__.Order object at 0x7f...>. Bo fixes it with Alex; Monty the sticker watches from the lid."] = "23:00。夜市摊位上最后一台点餐机器人靠一个叫 Order 的类运转。它的构造器没了，方法丢了第一个参数，收据打印出 <__main__.Order object at 0x7f...>。Bo 和 Alex 一起修；盖子上的贴纸 Monty 看着。",
  ["23:00. The last orders of the night hit three woks. The cook script runs them one after another. Threads will overlap the waiting; the GIL means they will not overlap the arithmetic. For frying, waiting is all that matters."] = "23:00。今晚最后几张订单落到三口锅上。烹饪脚本一个接一个地处理。线程会让等待重叠；GIL 意味着运算不会重叠。对煎东西来说，等待才是全部。",
  ["25 // 6 is 4, 25 / 6 is 4.1666. In Python 3 a single slash always makes a float."] = "25 // 6 是 4，25 / 6 是 4.1666。Python 3 里单条斜线总是得到 float。",
  ["25 eggs, 6 per tray: how many whole trays? Which operator divides and rounds down?"] = "25 个鸡蛋，每盘 6 个：几个完整的托盘？哪个运算符除完向下取整？",
  ["2^n subsets. When the output itself is exponential no algorithm can be faster; when only the answer is needed, look for a memo."] = "2^n 个子集。当输出本身就是指数级时，没有算法能更快；只需要答案时，去找 memo。",
  ["2^n subsets. When the output itself is exponential no algorithm can be faster; when only the answer is needed, look for a memo. The board is full."] = "2^n 个子集。当输出本身就是指数级时，没有算法能更快；只需要答案时，去找 memo。白板写满了。",
  ["2^n subsets. itertools.combinations lists them; when the output itself is exponential no algorithm can be faster."] = "2^n 个子集。itertools.combinations 把它们列出来；当输出本身就是指数级时，没有算法能更快。",
  ["3  ANSWER"] = "3  答案",
  ["4  ALL"] = "4  全部",
  ["4950. For 10,000 guests it is about fifty million. Big O ignores the /2, and rightly: the curve is the same."] = "4950。10,000 位客人就是大约五千万。Big O 忽略 /2，也理应如此：曲线是一样的。",
  ["4950. For 10,000 guests it is about fifty million. Big O ignores the /2: the curve is the same."] = "4950。10,000 位客人就是大约五千万。Big O 忽略 /2：曲线是一样的。",
  ["5  MARKDOWN"] = "5  MARKDOWN",
  ["6  CSV"] = "6  CSV",
  ["7  JSONL"] = "7  JSONL",
  ["7 streets. One language. Type the answers."] = "7 条街。一门语言。输入答案。",
  ["8  TXT"] = "8  TXT",
  ["9  SQLITE"] = "9  SQLITE",
  [":= declares and assigns. Type comes from the right-hand side."] = ":= 声明并赋值。类型来自右侧。",
  [":= infers the type. var names it. const never changes. int starts at 0."] = ":= 推断类型。var 写明类型。const 永不改变。int 从 0 开始。",
  ["< PREV"] = "< 上一步",
  ["<-chan T and chan<- T let the compiler stop the wrong side from sending or closing."] = "<-chan T 和 chan<- T 让编译器阻止错误的一方发送或关闭。",
  ["<= merges [1,3] and [3,5] into [1,5]. Use < if touching intervals should stay apart."] = "<= 会把 [1,3] 和 [3,5] 合并成 [1,5]。如果相接的区间要分开，用 <。",
  ["<= takes the left item on ties, so equal receipts keep their order. Merge is O(n); the whole sort O(n log n)."] = "<= 在打平时取左边的项，所以相同的收据保持顺序。合并是 O(n)；整个排序 O(n log n)。",
  ["? calls From::from on the error. Without the impl, use .map_err(OrderError::BadQty) by hand."] = "? 会对错误调用 From::from。没有这个 impl，就得手写 .map_err(OrderError::BadQty)。",
  ["? on Option returns None when it sees None. The function type must be Option as well."] = "Option 上的 ? 遇到 None 就返回 None。函数的返回类型也必须是 Option。",
  ["? unwraps Ok, or returns Err early from the function. Only works where the return type is Result or Option."] = "? 拆开 Ok，否则从函数提前返回 Err。只在返回类型是 Result 或 Option 的地方能用。",
  ["@classmethod gets cls; return cls(...) builds the right subclass too. The stamp desk closes."] = "@classmethod 拿到 cls；return cls(...) 连子类也能正确构建。盖章台关门。",
  ['@contextlib.___\ndef safe():\n    f = open("stock.csv")\n    try:\n        yield f\n    finally:\n        f.close()\n'] = '@contextlib.___\ndef safe():\n    f = open("stock.csv")\n    try:\n        yield f\n    finally:\n        f.close()\n',
  ["@contextlib.contextmanager: everything before yield is __enter__, everything after is __exit__. Ten lines become five."] = "@contextlib.contextmanager：yield 之前的一切是 __enter__，之后的一切是 __exit__。十行变五行。",
  ["@dataclass reads the annotated fields and writes the boilerplate. Order('tea', 2) just works. The shutter comes down; the night shift is closed."] = "@dataclass 读取带标注的字段并写好样板代码。Order('tea', 2) 直接可用。卷帘门落下；夜班结束。",
  ["@functools.___\ndef fib(n):\n    if n < 2:\n        return n\n    return fib(n - 1) + fib(n - 2)    # now O(n)\n"] = "@functools.___\ndef fib(n):\n    if n < 2:\n        return n\n    return fib(n - 1) + fib(n - 2)    # 现在是 O(n)\n",
  ["@functools.cache (3.9) memoizes by arguments; @lru_cache(maxsize=128) bounds it. fib(40) becomes 40 calls."] = "@functools.cache (3.9) 按参数记忆化；@lru_cache(maxsize=128) 限制大小。fib(40) 变成 40 次调用。",
  ["@functools.cache: a dict keyed by the arguments, O(1) per hit. Go spells this a comma-ok test; Rust memo.get(&n)."] = "@functools.cache：以参数为键的 dict，每次命中 O(1)。Go 写成 comma-ok 检查；Rust 写 memo.get(&n)。",
  ["@functools.wraps(fn) copies __name__, __doc__ and more onto the wrapper. Every decorator you write should use it."] = "@functools.wraps(fn) 把 __name__、__doc__ 等复制到包装器上。你写的每个装饰器都应该用它。",
  ["@property makes a getter; @total.setter adds assignment. Go would write a Total() method; Python hides the call."] = "@property 创建 getter；@total.setter 加上赋值。Go 会写一个 Total() 方法；Python 把调用藏起来。",
  ["@staticmethod: no implicit first argument. It is a namespaced plain function. Often a module-level def is clearer."] = "@staticmethod：没有隐含的第一个参数。它是一个带命名空间的普通函数。很多时候模块级的 def 更清楚。",
  ["@timer above def fry is exactly fry = timer(fry). Sugar, nothing more. Decorators stack, top one runs last."] = "def fry 上面的 @timer 就等于 fry = timer(fry)。纯语法糖，别无其他。装饰器可以叠加，最上面的最后应用。",
  ["A  ALL FORMATS"] = "A  全部格式",
  ["A DP table starts from the cases you can answer by hand. Everything else is built on them."] = "DP 表从你能手算出答案的情况开始。其他一切都建立在它们之上。",
  ["A Go release is a git tag: v1.0.0, pushed. go get pkg@latest picks the highest tag; no tag means a pseudo-version built from the commit. A breaking change is a new major, and a new major is a new import path: module github.com/you/x/v2. retract in go.mod tells everyone a tag was a mistake."] = "Go 的发布就是一个 git 标签：v1.0.0，推上去。go get pkg@latest 选最高的标签；没有标签就用由提交生成的伪版本。破坏性变更是新的主版本，而新的主版本就是新的导入路径：module github.com/you/x/v2。go.mod 里的 retract 告诉所有人某个标签打错了。",
  ["A Greek letter. Rust writes |o| o.1 for the same thing."] = "一个希腊字母。Rust 写 |o| o.1 做同样的事。",
  ["A ListNode holds val and next. Reverse with three names: prev, cur, nxt. Two runners find the middle; if the fast one meets the slow one, there is a cycle."] = "ListNode 持有 val 和 next。用三个名字反转：prev、cur、nxt。两个跑者找中点；快的追上慢的，就有环。",
  ["A Manager is convenience, not speed: every read and write is a round trip to another process. Fine for results, wrong for a hot loop."] = "Manager 图的是方便，不是速度：每一次读写都要往另一个进程跑一个来回。放结果可以，放在热循环里就错了。",
  ["A Node holds val, left, right; children start as None. Insert goes left when smaller. In-order walk prints sorted. Height is 1 + max of the children. BFS uses a deque and popleft."] = "Node 持有 val、left、right；子节点从 None 开始。插入时更小就往左。中序遍历打印排好序。高度是 1 + 子节点的 max。BFS 用 deque 和 popleft。",
  ["A Pool starts N interpreters once and feeds them work. pool.map keeps the order and waits for everything; imap yields results as they land; starmap unpacks tuples into several arguments; apply_async returns a handle whose get() blocks. chunksize decides how many items travel per trip, and for tiny tasks it is the whole game."] = "Pool 一次启动 N 个解释器，然后把活儿喂给它们。pool.map 保持顺序并等齐所有结果；imap 一到就交出来；starmap 把元组拆成多个参数；apply_async 返回一个句柄，它的 get() 会阻塞。chunksize 决定每趟运多少件，而对很小的任务来说，胜负全在它。",
  ["A Python list is your Go slice, minus the type. It just grows."] = "Python 的列表就是你的 Go 切片，去掉类型。它自己会长。",
  ["A Queue has no close(). What do you put on it to tell the workers to stop?"] = "Queue 没有 close()。你往上面放什么来告诉 worker 停下？",
  ["A Semaphore is a lock that lets n holders through. mp also has Event, Condition and Barrier, all with the threading names."] = "Semaphore 是一把允许 n 个持有者通过的锁。mp 还有 Event、Condition 和 Barrier，名字都和 threading 一样。",
  ["A String has one owner. Assigning moves it. & borrows, &mut borrows exclusively. Values drop at the end of their scope."] = "一个 String 只有一个所有者。赋值就是移动。& 借用，&mut 独占借用。值在作用域结束时 drop。",
  ["A Vec is a stack for free: the end is the top, and both ends of work are O(1)."] = "Vec 天生就是栈：末尾即栈顶，两头的操作都是 O(1)。",
  ["A Vec is your Go slice. An array knows its length at compile time."] = "Vec 就是你的 Go slice。数组在编译期就知道自己的长度。",
  ["A Vec<char> is the stack: push every opener, pop on every closer and compare. Valid when the stack ends empty. A second Vec of the smallest-so-far gives the minimum in O(1)."] = "Vec<char> 就是栈：遇到左括号就 push，遇到右括号就 pop 并比较。栈最终为空即有效。再用一个 Vec 记录到目前为止的最小值，就能 O(1) 取最小值。",
  ["A VecDeque grows at both ends in O(1). The stale end is the front, so eviction is a pop from there."] = "VecDeque 两端都能以 O(1) 增长。旧的一端是前端，所以淘汰就是从那里 pop。",
  ["A WaitGroup that carries an error, from golang.org/x/sync. Two words joined: err and group."] = "一个会带着 error 的 WaitGroup，来自 golang.org/x/sync。两个词拼起来：err 和 group。",
  ["A bang. vec! and format! end the same way."] = "一个感叹号。vec! 和 format! 的结尾也一样。",
  ["A bool method on every collection, two words joined by an underscore. Not len() == 0, though that works too."] = "每种集合都有的 bool 方法，两个单词用下划线连接。不是 len() == 0，虽然那样也行。",
  ["A buffered channel blocks only when full. Unbuffered blocks on every send until someone receives."] = "有缓冲的 channel 只在满时阻塞。无缓冲的每次发送都阻塞，直到有人接收。",
  ["A buffered channel is a counting semaphore. golang.org/x/sync/semaphore is the weighted version."] = "带缓冲 channel 就是计数信号量。golang.org/x/sync/semaphore 是加权版本。",
  ["A buffered channel of capacity 4 is a counting semaphore: the fifth send blocks until a trip finishes."] = "容量为 4 的带缓冲 channel 就是一个计数信号量：第五次发送会阻塞，直到有一趟送完。",
  ["A call that can fail returns Result. Handle Err, or pass it up with ?."] = "可能失败的调用返回 Result。处理 Err，或者用 ? 往上传。",
  ["A channel that holds 3 muffins before a send blocks. Fill: make(chan string, ___)"] = "能存 3 个松饼才阻塞发送的 channel。填空：make(chan string, ___)",
  ["A closed channel never blocks again, so a for-range over it ends and a bare receive returns instantly, for ever."] = "已关闭的 channel 再也不会阻塞，所以对它的 for-range 会结束，而单纯的接收会永远立刻返回。",
  ["A closer must match the most recent opener. Which method removes and returns the top?"] = "闭括号必须匹配最近的开括号。哪个方法移除并返回栈顶？",
  ["A closer must match the most recent opener. Which method takes the top off and returns Option<char>?"] = "右括号必须匹配最近的左括号。哪个方法取走栈顶并返回 Option<char>？",
  ["A closer must match the top of the stack. Which map gives the opener it needs?"] = "闭括号必须匹配栈顶。哪个 map 给出它需要的开括号？",
  ["A closer names the opener it needs. Finish the match: '}' wants which char?"] = "右括号说出它需要的左括号。补全匹配：'}' 需要哪个字符？",
  ["A closure captures n. Each call to add(2) has its own n."] = "闭包捕获 n。每次调用 add(2) 都有自己的 n。",
  ["A cold coffee came back. The app says 'error' and nothing else."] = "一杯凉咖啡被退回来了。app 只显示 'error'，别的什么也没说。",
  ["A compile-time value with an UPPER_CASE name and a required type. Which keyword?"] = "编译期的值，名字全大写，必须写类型。哪个关键字？",
  ["A constraint that allows int and every type built on int. Fill: ___int | ___float64"] = "允许 int 以及所有基于 int 的类型的约束。填空：___int | ___float64",
  ["A context is the cancel signal of a request. It travels as the first parameter, named ctx, never inside a struct. WithCancel and WithTimeout wrap a parent and hand back a cancel function you always defer. Work watches ctx.Done() and reports ctx.Err(), which is Canceled or DeadlineExceeded."] = "context 是一个请求的取消信号。它作为第一个参数传递，名字叫 ctx，绝不放进 struct 里。WithCancel 和 WithTimeout 包住父 context，并交回一个你总要 defer 的 cancel 函数。工作盯着 ctx.Done()，并报告 ctx.Err()，也就是 Canceled 或 DeadlineExceeded。",
  ["A cook locks the rail, pulls one ticket, releases. Which Receiver method blocks until a job arrives?"] = "厨师锁住轨，取一张单，然后放开。哪个 Receiver 方法会阻塞到有任务来？",
  ["A cook takes the next order, waiting if the queue is empty. Which method?"] = "一个厨师取下一张订单，队列为空就等。哪个方法？",
  ["A copied mutex protects nothing. Anything holding a sync type gets pointer receivers, and never travels by value."] = "被复制的 mutex 什么都保护不了。凡是持有 sync 类型的东西都用指针接收者，绝不按值传递。",
  ["A counter every process can see. Which attribute reads and writes the shared number?"] = "一个每个进程都看得到的计数器。哪个属性读写那个共享数字？",
  ["A counter no mutex guards. Which sync/atomic type holds a 64-bit int?"] = "一个不用 mutex 守护的计数器。sync/atomic 的哪个类型装 64 位整数？",
  ["A crash you can catch in the same goroutine. Which pair: panic and ___?"] = "同一个 goroutine 里能接住的崩溃。哪一对：panic 和 ___？",
  ['A crate writes Display and Error for you from #[error("..")]. Its name?'] = '有个 crate 能从 #[error("..")] 替你写出 Display 和 Error。它叫什么？',
  ["A customer typed 1x8 sets and the till printed a page of panic. Ticket two."] = "有顾客输入了 1x8 份，收银机打出了一整页 panic。第二张工单。",
  ["A daemon child is terminated when the parent exits, and it may not have children of its own. Use it for watchers, never for work you need finished."] = "daemon 子进程在父进程退出时会被终止，而且它自己不能有子进程。用它做监视，绝不要用来做你需要完成的工作。",
  ["A decorator is a function that takes a function and returns a new one; @name applies it. functools.wraps keeps the name. @property, @staticmethod and @classmethod are built-in decorators."] = "装饰器是一个接收函数并返回新函数的函数；@name 应用它。functools.wraps 保住名字。@property、@staticmethod 和 @classmethod 是内置装饰器。",
  ["A def with no return evaluates to None. Printing that is a classic beginner surprise. The pass window is done."] = "没有 return 的 def 求值为 None。把它打印出来是初学者的经典惊讶。出餐窗口完成。",
  ["A dict from closer to opener. Looking up a closer is O(1); no chain of ifs."] = "从闭括号到开括号的 dict。查一个闭括号是 O(1)；不用一串 if。",
  ["A dict maps keys to values: {} makes one, d[k] reads, d.get(k, default) reads safely, .items() walks pairs, del removes. set() keeps unique items."] = "dict 把键映射到值：{} 创建一个，d[k] 读取，d.get(k, default) 安全读取，.items() 遍历键值对，del 删除。set() 只保留唯一项。",
  ["A dict that also remembers which key is oldest. Which class from collections?"] = "一个还记得哪个键最老的 dict。collections 里的哪个类？",
  ["A directory that builds into a program declares which package?"] = "会构建成程序的目录声明哪个包？",
  ["A done signal that carries no data. Fill the element type: make(chan ___)"] = "不带数据的完成信号。填元素类型：make(chan ___)",
  ["A dot, then the word for waiting. Only allowed inside an async block or fn."] = "一个点，然后是表示等待的那个词。只能在 async 块或 async fn 里用。",
  ["A field with no name, only the type. That is embedding."] = "没有名字、只有类型的字段。这就是嵌入。",
  ["A fixed [26]int beats a map for lowercase ASCII. Then check every count == 0."] = "小写 ASCII 用固定的 [26]int 胜过 map。然后检查每个计数 == 0。",
  ["A fixed array of exactly 3 frames, size in the type. Fill: var frames ___"] = "恰好 3 帧的定长数组，大小写在类型里。填空：var frames ___",
  ["A fixed tray of three prices. The array type spells out its length. Which number?"] = "固定装三个价格的托盘。数组类型写明长度。哪个数字？",
  ["A fixed window is O(n), not O(n*k): every element enters once and leaves once."] = "定长窗口是 O(n)，不是 O(n*k)：每个元素进一次、出一次。",
  ["A flag: dash then four letters. Works with run and build too."] = "一个标志：横杠加四个字母。run 和 build 也能用。",
  ["A folder is a package"] = "一个文件夹就是一个包",
  ["A fresh node has no children yet. What are left and right set to?"] = "新节点还没有子节点。left 和 right 设成什么？",
  ["A function that can fail returns a value and an ___."] = "可能失败的函数返回一个值和一个 ___。",
  ["A function that can fail returns which type?"] = "可能失败的函数返回哪个类型？",
  ["A function that remembers n after ident returns. What is that function called?"] = "在 ident 返回后仍记得 n 的函数。这种函数叫什么？",
  ["A function that runs once before main, and nobody calls it. Its name?"] = "在 main 之前运行一次、没人调用它的函数。叫什么？",
  ["A function, past tense, returning a new list. names.sort(key=len) would do it in place."] = "一个函数，过去式，返回新列表。names.sort(key=len) 会就地排序。",
  ["A function, past tense. The method prices.sort() would change the list in place and return None."] = "一个函数，过去式。方法 prices.sort() 会就地修改列表并返回 None。",
  ["A gap: this shift starts after the last block ended. Start a new block. Which list method?"] = "有空隙：这个班次在上一个块结束后才开始。开一个新块。哪个列表方法？",
  ["A generator is a Rust iterator that writes itself. yield instead of impl Iterator."] = "生成器是一个自己写自己的 Rust 迭代器。用 yield 代替 impl Iterator。",
  ["A go.work is a list of use directories and optional replaces. It never lists versions: those still come from each module's own go.mod."] = "go.work 就是一串 use 目录加可选的 replace。它从不列版本：版本仍然来自每个模块自己的 go.mod。",
  ["A goroutine is cheap. Don't confuse it with a thread you create by hand."] = "goroutine 很便宜。别和手动创建的线程混淆。",
  ["A goroutine is not an OS thread: the runtime multiplexes many of them onto GOMAXPROCS threads, so a pool sized by runtime.NumCPU() is the usual answer for CPU work. WaitGroup counts the workers, a buffered channel works as a semaphore, and sync.Pool recycles the buffers they allocate."] = "goroutine 不是 OS 线程：运行时把很多 goroutine 复用到 GOMAXPROCS 条线程上，所以做 CPU 工作时，池子大小取 runtime.NumCPU() 是常见答案。WaitGroup 数着 worker，带缓冲的 channel 就是信号量，而 sync.Pool 回收它们分配的缓冲区。",
  ["A goroutine that nobody waits for and nothing cancels is a leak: it holds its stack and whatever it captured until the process ends."] = "没人等、也没有东西取消的 goroutine 就是泄漏：它会一直占着自己的栈和捕获的东西，直到进程结束。",
  ["A graph is a dict of lists: defaultdict(list). BFS uses a deque and a visited set; DFS recurses. Mark a node visited when you enqueue it, not when you pop it."] = "图是一个列表的 dict：defaultdict(list)。BFS 用 deque 和 visited 集合；DFS 递归。节点在入队时标记已访问，不是出队时。",
  ["A grid is a graph without an adjacency list. Count islands: for every land cell, count one and sink the whole island with a recursive flood that stops at the edges and at water. usize needs wrapping_sub for 'row minus one'."] = "网格是一张没有邻接表的图。数岛屿：对每个陆地格计一个，然后用递归洪泛把整座岛沉掉，在边缘和水面停下。usize 做“行减一”需要 wrapping_sub。",
  ["A grid is a graph: each cell has four neighbours. Flood fill: stop off the map or on water, sink the cell, recurse four ways. Count one island per unsunk land cell in the double loop."] = "网格就是图：每个格子有四个邻居。洪水填充：出了地图或碰到水就停，沉掉这个格子，向四个方向递归。双重循环里每遇到一个没沉的陆地格就算一座岛。",
  ["A handful of index variables, however long the Vec. Constant."] = "几个索引变量，不管 Vec 多长。常数。",
  ["A handful of index variables, however long the list. Constant."] = "几个索引变量，不管列表多长。常数。",
  ["A handful of index variables, however long the slice. Constant."] = "几个索引变量，不管切片多长。常数。",
  ["A heap is a list whose front is its root. The front index."] = "堆是一个列表，它的最前面就是堆顶。最前面的下标。",
  ["A heap of size k, Mei. Rust's is a max-heap, so you'll need the little wrapper that flips it."] = "一个大小为 k 的堆，Mei。Rust 的是最大堆，所以你需要那个把它翻过来的小包装。",
  ["A heap pointer to a dyn trait: Box, angle brackets, dyn, the trait."] = "指向 dyn trait 的堆指针：Box、尖括号、dyn、那个 trait。",
  ["A helper inside the class that needs neither self nor the class. Which decorator?"] = "类里一个既不需要 self 也不需要类的辅助函数。哪个装饰器？",
  ["A hit: the key was just used, so it becomes the newest. Which OrderedDict method?"] = "命中：这个键刚被用过，所以变成最新的。哪个 OrderedDict 方法？",
  ["A linear scan. Found early is lucky; Big O counts the worst case, n. A HashSet<String> makes it O(1)."] = "线性扫描。早找到算运气；Big O 数的是最差情况，n。用 HashSet<String> 就变成 O(1)。",
  ["A linear scan. Found early is lucky; Big O counts the worst case, n. A map[string]bool makes it O(1)."] = "线性扫描。早找到算运气；Big O 数的是最差情况，n。用 map[string]bool 就变成 O(1)。",
  ["A list grows with append and shrinks with pop. len counts. a[1:3] slices, a[-1] is the last item. [f(x) for x in a] builds a new list. sorted returns a new list."] = "列表用 append 变长，用 pop 变短。len 计数。a[1:3] 切片，a[-1] 是最后一项。[f(x) for x in a] 构建新列表。sorted 返回新列表。",
  ["A list is Option<Box<ListNode>>. take() moves a node out and leaves None. Reverse with prev and cur; slow and fast runners find the middle."] = "链表就是 Option<Box<ListNode>>。take() 把一个节点移出来，原地留下 None。用 prev 和 cur 反转；快慢指针找中点。",
  ["A list is a stack: append pushes, pop takes the top, st[-1] peeks. Openers go on, closers must match the top. A second list of running minimums makes a min stack."] = "列表就是栈：append 压入，pop 取走栈顶，st[-1] 窥视。开括号入栈，闭括号必须与栈顶匹配。再用一个列表记录当前最小值，就是最小栈。",
  ["A list is not an iterator; get one from it. Which built-in?"] = "列表不是迭代器；从它取一个出来。哪个内置函数？",
  ["A list of order names. Which built-in generic, lowercase since 3.9?"] = "订单名字的列表。哪个内置泛型，3.9 起用小写？",
  ["A list of the dishes on the board, just the names. Which method?"] = "菜单板上菜名的列表，只要名字。哪个方法？",
  ["A loop over n guests inside a loop over m tables. The two sizes differ. Cost?"] = "遍历 m 张桌子的循环里遍历 n 位客人。两个大小不同。代价？",
  ["A loop over n guests inside a loop over the same n guests. Cost, in Big O?"] = "遍历 n 位客人的循环里再遍历同样 n 位客人。用 Big O 说代价多少？",
  ["A loop that returns a value? Go cannot do that."] = "会返回值的循环？Go 可做不到。",
  ["A major.minor like 1.23. Since Go 1.21 it is a real floor: an older toolchain will fetch a newer one."] = "像 1.23 这样的 major.minor。从 Go 1.21 起这是真正的下限：旧工具链会自动去取新的。",
  ["A map built on hashing, CapWords. A Vec of pairs would need a scan, O(n)."] = "基于哈希的 map，CapWords。成对的 Vec 需要扫描，O(n)。",
  ["A map entry pointing at a removed node is a bug waiting: the map and the list must always agree."] = "map 条目指向一个已删除的节点，就是等着爆发的 bug：map 和链表必须始终一致。",
  ["A map finds it, a list remembers the order. Two structures that agree."] = "map 负责找到它，链表负责记住顺序。两个结构，步调一致。",
  ['A map from string to int. Fill the type: prices := ___{"muffin": 18}'] = '从 string 到 int 的 map。填入类型：prices := ___{"muffin": 18}',
  ["A map is a hash table. comma-ok tells you if the key was there. delete removes it."] = "map 是哈希表。comma-ok 告诉你键在不在。delete 删除它。",
  ["A map of last positions lets the left edge jump instead of creeping one step at a time."] = "一张上次位置的 map 让左边缘可以跳跃，而不是一步一步挪。",
  ["A map turns 'does this closer match?' into one lookup. Openers are the values, closers the keys."] = "一个 map 把“这个闭括号匹配吗？”变成一次查找。开括号是值，闭括号是键。",
  ["A map turns O(n^2) two-sum into O(n). Two pointers check a palindrome. A [26]int counts letters."] = "map 把 O(n^2) 的两数之和变成 O(n)。双指针判回文。[26]int 数字母。",
  ["A match guard does the test. With < instead, (1,3) and (3,5) would stay apart; ask the interviewer which they want."] = "match 守卫做判断。换成 <，(1,3) 和 (3,5) 就会分开；问问面试官要哪种。",
  ["A method on context.Context. Its channel closes on cancel."] = "context.Context 的一个方法。取消时它的 channel 会关闭。",
  ["A method that changes the order needs a pointer receiver. Fill: func (o ___) Add(p int)"] = "修改订单的方法需要指针接收者。填空：func (o ___) Add(p int)",
  ["A min stack answers the minimum in O(1). Each push also records the smaller of x and the old low. Which built-in?"] = "最小栈 O(1) 回答最小值。每次 push 也记下 x 和旧最小值中较小的那个。哪个内置函数？",
  ["A min stack answers the minimum in O(1): a second slice keeps the running minimum. What is pushed onto low?"] = "最小栈用 O(1) 回答最小值：第二个切片记录当前最小值。往 low 里压入的是什么？",
  ["A miss: compute it from the two smaller ones. Fill the second call: fib(___, memo)"] = "未命中：用两个更小的值算出来。填第二次调用：fib(___, memo)",
  ["A module is a tree of packages with one go.mod at its root. go mod init names it, and that name is the prefix of every import path inside it, so name it after the repo: github.com/you/project. The go directive is the minimum toolchain. Modules have been the only mode since Go 1.16; GOPATH is history."] = "模块是一棵包的树，根目录有且只有一个 go.mod。go mod init 给它起名，而这个名字就是里面每条导入路径的前缀，所以按仓库来起名：github.com/you/project。go 指令是最低工具链版本。从 Go 1.16 起模块是唯一的模式；GOPATH 已经是历史。",
  ["A move. Integers are Copy and stay valid; a String is moved and the old name dies. No double free, ever."] = "移动（move）。整数是 Copy，保持有效；String 被移动，旧名字失效。永远不会双重释放。",
  ["A mutex for a single int is a lot of ceremony for one number."] = "为了一个 int 用 mutex，仪式感也太强了。",
  ["A name that cannot be assigned later. Which keyword?"] = "之后不能再赋值的名字。哪个关键字？",
  ["A new neighbour: mark it seen when you enqueue it. Which set method?"] = "一个新邻站：入队时就标记见过。哪个 set 方法？",
  ["A nil *Order stored in an interface. Is the interface == nil? It prints ___"] = "一个 nil 的 *Order 存进 interface。这个 interface == nil 吗？它打印 ___",
  ["A nil map panics when you write to it. Allocate one: floors = ___(map[string]int)"] = "向 nil map 写入会 panic。分配一个：floors = ___(map[string]int)",
  ["A node points at two children of its own type. Fill the field type: Left, Right ___"] = "节点指向两个同类型的子节点。填字段类型：Left, Right ___",
  ["A phone book: open the middle, decide left or right, throw half away. Again."] = "电话簿：翻开中间，决定左还是右，扔掉一半。再来。",
  ["A pipe that carries string. Fill: ch := make(___)"] = "传送 string 的管道。填空：ch := make(___)",
  ["A pointer receiver: a star before the type name."] = "指针接收者：类型名前面一个星号。",
  ["A pointer to Order. Fill the type of p: var p ___Order"] = "指向 Order 的指针。填入 p 的类型：var p ___Order",
  ["A pointer to the node type of container/list."] = "指向 container/list 节点类型的指针。",
  ["A pointer, or the struct would contain itself forever. Star then the type."] = "用指针，否则 struct 会无限包含自己。星号后接类型。",
  ["A range with two dots, like Go's [1:3]."] = "两个点的范围，像 Go 的 [1:3]。",
  ["A receive-only parameter makes the compiler enforce the direction: a worker that tries to send on jobs will not build."] = "只收不发的参数让编译器强制方向：想往 jobs 里发送的 worker 根本编译不过。",
  ["A recursive def needs a base case and a smaller call. A dict memo or @functools.cache turns fib from 2^n into n."] = "递归 def 需要一个基准情况和一个更小的调用。dict memo 或 @functools.cache 把 fib 从 2^n 变成 n。",
  ["A recursive fn needs a base case and a smaller call. A HashMap memo turns fib from 2^n into n."] = "递归 fn 需要一个 base case 和一次更小的调用。HashMap memo 把 fib 从 2^n 变成 n。",
  ["A recursive func needs a base case and a smaller call. A memo map turns fib from 2^n into n."] = "递归函数需要基准情形和更小的调用。一个 memo map 把 fib 从 2^n 变成 n。",
  ["A reference must not outlive what it points at. 'a names how long; 'static means the whole program."] = "引用不能活得比它指向的东西久。'a 给这段时长起名；'static 表示整个程序期间。",
  ["A repo grows a shape: cmd/<name>/main.go per binary, internal/ for packages the compiler refuses to let outsiders import, a doc comment on every package, and menu_test.go in package menu_test so the tests use the package the way a caller would."] = "仓库会长出形状：每个二进制一个 cmd/<name>/main.go，编译器不许外人导入的包放 internal/，每个包一条文档注释，还有写成 package menu_test 的 menu_test.go，让测试像调用者一样使用这个包。",
  ["A room frees up when this start is not before the earliest end."] = "这个起点不早于最早的终点时，就有一间房空出来。",
  ["A seat number that may not exist. Which type wraps a value that can be missing?"] = "一个可能不存在的座位号。哪个类型包装可能缺失的值？",
  ["A second test after an if. Which keyword is Python's 'else if'?"] = "if 之后的第二次判断。Python 的“else if”是哪个关键字？",
  ["A sentinel error value the whole package can compare against. Fill: errors.___"] = "一个整个包都能拿来比较的哨兵 error 值。填：errors.___",
  ["A sentinel infinity. math.MaxInt would overflow the moment you add 1 to it."] = "一个哨兵无穷大。math.MaxInt 一加 1 就会溢出。",
  ["A set answers 'seen?' in O(1). A list would make BFS O(n^2)."] = "set 用 O(1) 回答“见过吗？”。用 list 会让 BFS 变成 O(n^2)。",
  ["A set built on hashing, CapWords, in std::collections. insert returns false when the value was already in."] = "基于哈希的集合，CapWords，在 std::collections 里。值已经存在时 insert 返回 false。",
  ["A set of methods, no fields. Which keyword?"] = "一组方法，没有字段。哪个关键字？",
  ["A set of seen stations. Fill the value type: map[string]___"] = "已访问车站的集合。填值类型：map[string]___",
  ["A size is Small or Large and nothing else. Which keyword lists the variants?"] = "尺寸只有 Small 或 Large，再无其他。哪个关键字列出变体？",
  ["A slice is Go's stack: this pushes, st[:len(st)-1] pops. Both O(1), amortized."] = "切片就是 Go 的栈：这一步入栈，st[:len(st)-1] 出栈。两者均摊都是 O(1)。",
  ["A slice is a stack: append pushes, st[:len(st)-1] pops. Push every opener, match every closer against the top, valid when the stack ends empty. A min stack keeps a second stack of running minimums."] = "切片就是栈：append 入栈，st[:len(st)-1] 出栈。每个开括号入栈，每个闭括号与栈顶比对，最后栈空即有效。最小栈另外维护一个记录当前最小值的栈。",
  ["A slice is a view: pointer, len, cap. append may grow it. len is the length."] = "slice 是视图：指针、len、cap。append 可能让它增长。len 是长度。",
  ["A slice is a window, not a copy. Both look at the same memory."] = "slice 是窗口，不是副本。两者看的是同一块内存。",
  ["A slice of int, not a fixed array. Fill the type: s := ___{1, 2, 3}"] = "int 的 slice，不是定长数组。填入类型：s := ___{1, 2, 3}",
  ["A sorted copy of the prices, leaving the original as it is. Which built-in?"] = "价格的排序副本，原列表保持不变。哪个内置函数？",
  ["A sorted copy, leaving the original untouched, needs a second Vec. Extra space: O(___)"] = "一份有序副本，原样保留原 Vec，需要第二个 Vec。额外空间：O(___)",
