  ["After the loop append the leftovers: out = append(out, l[i:]...) and r[j:]..."] = "循环后追加剩余部分：out = append(out, l[i:]...) 以及 r[j:]...",
  ["After the loop the heap holds the k biggest and the smallest of them is on top: the kth largest. Which method reads the top without removing it?"] = "循环结束后堆里是最大的 k 个，其中最小的在堆顶：也就是第 k 大。哪个方法读取堆顶而不移除？",
  ["After the loop, k items remain and the kth largest is the smallest of them. Which index holds it?"] = "循环结束后剩 k 个元素，第 k 大就是其中最小的。哪个下标存着它？",
  ["After the loop, what makes the string valid? Every opener found its closer, so the stack is what?"] = "循环结束后，字符串怎样才算有效？每个左括号都找到了右括号，那么栈应该是什么状态？",
  ["Alex"] = "Alex",
  ["Alias for interface{}. The constraint that allows every type."] = "interface{} 的别名。允许所有类型的约束。",
