  ["BST rule: everything smaller is in the left subtree. &mut n.left reborrows the child for the recursive call."] = "BST 规则：所有更小的都在左子树。&mut n.left 为递归调用重新借用子节点。",
  ["Bake menu.json into the binary at compile time. Fill the directive: //go:___"] = "编译时把 menu.json 打进二进制文件。填指令：//go:___",
  ["Base case first, always. Without it Python raises RecursionError at depth 1000."] = "基准情况永远先行。没有它 Python 会在深度 1000 处抛出 RecursionError。",
  ["Base case first, always. Without it the stack overflows."] = "永远先写基准情形。没有它栈就会溢出。",
