  ["Map keys must support ==. Fill the constraint: func Has[K ___](m map[K]bool, k K)"] = "map 的键必须支持 ==。填约束：func Has[K ___](m map[K]bool, k K)",
  ["Maps"] = "Map",
  ["Mark a function so calling it returns a Future instead of running. Which keyword?"] = "标记一个函数，让调用它返回 Future 而不是直接运行。哪个关键字？",
  ["Mark on enqueue, not on dequeue, or a station can be queued twice from two neighbours."] = "入队时标记，不是出队时，否则一个车站可能从两个邻站被入队两次。",
  ["Mark the cell visited by sinking it. What is written into the grid?"] = "把格子沉掉以标记已访问。往网格里写入什么？",
  ["Mark the cell visited by turning it into water. Fill the value."] = "把格子变成水来标记已访问。填这个值。",
  ["Marking in place is the visited set: O(1) extra space. Interviewers may ask you not to mutate; then use a HashSet<(usize, usize)>."] = "就地标记就是 visited 集合：O(1) 额外空间。面试官可能要求不修改输入；那就用 HashSet<(usize, usize)>。",
