  ["fn fib(n: u64) -> u64 {\n    if n < 2 { return n; }\n    fib(n - 1) + fib(n - 2)   // ___ : two calls each\n}\n"] = "fn fib(n: u64) -> u64 {\n    if n < 2 { return n; }\n    fib(n - 1) + fib(n - 2)   // ___ ：每次两个调用\n}\n",
  ["fn fib(n: u64, memo: &mut HashMap<u64, u64>) -> u64 {\n    if let Some(&v) = memo.___(&n) { return v; }\n    let v = if n < 2 { n } else { fib(n - 1, memo) + fib(n - 2, memo) };\n    memo.insert(n, v);\n    v\n}\n"] = "fn fib(n: u64, memo: &mut HashMap<u64, u64>) -> u64 {\n    if let Some(&v) = memo.___(&n) { return v; }\n    let v = if n < 2 { n } else { fib(n - 1, memo) + fib(n - 2, memo) };\n    memo.insert(n, v);\n    v\n}\n",
  ["fn fib(n: u64, memo: &mut HashMap<u64, u64>) -> u64 {\n    if n < 2 {\n        return n;\n    }\n    if let Some(&v) = memo.___(&n) {   // seen before?\n        return v;\n    }\n"] = "fn fib(n: u64, memo: &mut HashMap<u64, u64>) -> u64 {\n    if n < 2 {\n        return n;\n    }\n    if let Some(&v) = memo.___(&n) {   // 之前见过吗？\n        return v;\n    }\n",
