  ["fn get(&mut self, k: u32) -> Option<&String> {\n    // used just now: move k to the back, the fresh end\n    if let Some(i) = self.order.iter().___(|&&x| x == k) {\n        self.order.remove(i);\n        self.order.push_back(k);\n    }\n    self.map.get(&k)\n"] = "fn get(&mut self, k: u32) -> Option<&String> {\n    // 刚用过：把 k 移到末尾，新的那端\n    if let Some(i) = self.order.iter().___(|&&x| x == k) {\n        self.order.remove(i);\n        self.order.push_back(k);\n    }\n    self.map.get(&k)\n",
