  ["jobs = [(p, 512) for p in photos]\nwith mp.Pool(8) as pool:\n    pool.___(resize, jobs)\n"] = "jobs = [(p, 512) for p in photos]\nwith mp.Pool(8) as pool:\n    pool.___(resize, jobs)\n",
  ["jobs.join() returns when every put has a matching task_done. daemon=True lets the idle cooks die with main. Seven rounds, no misses. HIRED, at midnight, in Python."] = "jobs.join() 在每个 put 都配上 task_done 时返回。daemon=True 让空闲的厨师随主线程一起结束。七个回合零失误。午夜，用 Python，HIRED。",
  ["join! waits for all; select! returns on the first. 200 ms total instead of 400."] = "join! 等全部完成；select! 第一个完成就返回。总共 200 ms 而不是 400。",
  ["join() blocks until the child exits. Without it the parent can reach the end of the script and leave orphans behind."] = "join() 会阻塞到子进程退出为止。没有它，父进程可能跑到脚本末尾，留下一堆孤儿进程。",
  ["join() blocks until the thread ends and returns Result<T>; Err means the thread panicked. 180 seconds to steep."] = "join() 阻塞到线程结束，返回 Result<T>；Err 表示线程 panic 了。泡 180 秒。",
  ["json only sees exported fields. Name the item field: Item or item?"] = "json 只看得到导出字段。给菜品字段起名：Item 还是 item？",
  ["json sees exported fields only. Tags pick the key. Marshal out, Unmarshal in."] = "json 只看导出字段。tag 选 key。Marshal 出，Unmarshal 进。",
  ["k contenders left; the smallest of them is the kth largest overall. Which index holds it?"] = "剩下 k 个候选；其中最小的就是全局第 k 大。哪个下标放着它？",
  ["k positions behind the newest one."] = "比最新那个落后 k 个位置。",
  ["kb = 2 ___ 10\nprint(kb)          # 1024\n"] = "kb = 2 ___ 10\nprint(kb)          # 1024\n",
  ["key= is called once per item; sort by its result. sorted(words, key=str.lower) is the case-insensitive classic."] = "key= 对每一项调用一次；按它的结果排序。sorted(words, key=str.lower) 是不区分大小写的经典。",
  ["kth largest: keep only the k biggest in a MIN-heap, so the smallest of them sits on top. BinaryHeap is a max-heap: which std::cmp wrapper flips the order?"] = "第 k 大：只在一个最小堆里保留最大的 k 个，这样其中最小的在堆顶。BinaryHeap 是最大堆：哪个 std::cmp 包装类型能翻转顺序？",
  ["l only moves right, so each character enters and leaves once: O(n) despite the nested while."] = "l 只向右移，所以每个字符进出各一次：虽然嵌套了 while 仍是 O(n)。",
  ["l[i] <= r[j] keeps the merge stable. The leftovers are appended with extend. O(n) per merge."] = "l[i] <= r[j] 让合并保持稳定。剩下的用 extend 接在后面。每次合并 O(n)。",
  ['label := fmt.___("%s $%d", item, price)   // "set $25"\n'] = 'label := fmt.___("%s $%d", item, price)   // "set $25"\n',
  ["lambda o: o[1] is an anonymous one-expression function. For anything longer, use def."] = "lambda o: o[1] 是只有一个表达式的匿名函数。再长一点就用 def。",
  ["largest compares with >. Which trait must T promise?"] = "largest 用 > 比较。T 必须承诺哪个 trait？",
  ["last := items[len(items)___]    // still O(1): len is stored\n"] = "last := items[len(items)___]    // 仍然 O(1)：len 是存好的\n",
  ["last := map[rune]int{}\nl, best := 0, 0\nfor r, c := range s {\n    if p, ok := last[c]; ok && p >= l {\n        l = p + 1           // jump past the repeat\n    }\n    last[c] = ___\n"] = "last := map[rune]int{}\nl, best := 0, 0\nfor r, c := range s {\n    if p, ok := last[c]; ok && p >= l {\n        l = p + 1           // 跳过重复项\n    }\n    last[c] = ___\n",
  ["last = items[___]    # still O(1): negative indexes count from the end\n"] = "last = items[___]    # 仍然 O(1)：负索引从末尾数起\n",
  ["latest means the highest tagged release, never a pre-release and never main. Without any tag at all you get a pseudo-version like v0.0.0-20260904164500-abc123def456."] = "latest 意味着最高的已打标签发布，绝不是预发布，也绝不是 main。完全没有标签时你会得到像 v0.0.0-20260904164500-abc123def456 这样的伪版本。",
  ["len counts bytes. 灣 is one character. In UTF-8, how many bytes?"] = "len 数的是字节。灣 是一个字符。在 UTF-8 里占几个字节？",
  ["len is how many you can see. cap is how many fit before a new array."] = "len 是你能看到的个数。cap 是换新数组之前能装的个数。",
  ["len is what is waiting, cap is the buffer size. A buffer smooths bursts; it never removes the need to handle a slow consumer."] = "len 是正在等的东西，cap 是缓冲区大小。缓冲能抹平突发流量；它从不免除你处理慢消费者的责任。",
  ["len works on lists, strings, dicts, sets, anything with __len__. It is O(1): the length is stored."] = "len 对列表、字符串、dict、set，任何有 __len__ 的东西都行。它是 O(1)：长度是存好的。",
  ["len() is bytes. Slicing &s[0..4] in the middle of 鑼 panics: not a char boundary."] = "len() 是字节数。&s[0..4] 切在 鑼 的中间会 panic：不是字符边界。",
  ["len() returns usize. The second let shadows n with a new binding; the old one is gone. Next tram in 7."] = "len() 返回 usize。第二个 let 用新绑定遮蔽了 n；旧的没了。下一班电车 7 分钟。",
  ["len(a) // 2 splits [3, 1, 2] into [3] and [1, 2]. Each level halves; log2(n) levels."] = "len(a) // 2 把 [3, 1, 2] 分成 [3] 和 [1, 2]。每层减半；log2(n) 层。",
