  ["let mut n = 0;\nfor r in 0..g.len() {\n    for c in 0..g[0].len() {\n        // land still standing: a new island, flood it\n        if g[r][c] == b'1' { n += 1; ___(&mut g, r, c); }\n    }\n}\n"] = "let mut n = 0;\nfor r in 0..g.len() {\n    for c in 0..g[0].len() {\n        // 还立着的陆地：一座新岛，洪泛它\n        if g[r][c] == b'1' { n += 1; ___(&mut g, r, c); }\n    }\n}\n",
