  ['luckymac/           module github.com/alex/luckymac\n  menu/price.go     import "github.com/alex/luckymac/___"\n  rider/eta.go      import "github.com/alex/luckymac/rider"\n'] = 'luckymac/           module github.com/alex/luckymac\n  menu/price.go     import "github.com/alex/luckymac/___"\n  rider/eta.go      import "github.com/alex/luckymac/rider"\n',
  ["m := <-res blocks this goroutine, not the program. That is exactly what await does, minus the keyword and minus the coloured functions."] = "m := <-res 阻塞的是这个 goroutine，不是整个程序。这正是 await 做的事，只是少了关键字，也少了被染色的函数。",
  ["macOS and Windows do not fork by default. Name their start method."] = "macOS 和 Windows 默认不用 fork。说出它们的启动方式。",
  ["main calls menu.Price and the compiler says undefined. Fix the name."] = "main 调用 menu.Price，编译器说 undefined。改对名字。",
  ["main can fail in many ways. Which pointer type wraps any dyn Error?"] = "main 有很多种失败方式。哪种指针类型能包住任何 dyn Error？",
  ["main sends on an unbuffered channel with nobody receiving. The runtime reports: all goroutines are asleep - ___!"] = "main 向无缓冲 channel 发送，却没人接收。运行时报告：all goroutines are asleep - ___!",
  ["make (or a {} literal) before the first write. Reading a nil map is safe."] = "第一次写入前先 make（或 {} 字面量）。读 nil map 是安全的。",
  ["make(T, len, cap) for slices, maps, channels. new(T) only gives a zeroed pointer."] = "make(T, len, cap) 用于 slice、map、channel。new(T) 只给一个指向零值的指针。",
  ["make([]int, len(a)) then copy. Allocation is where space complexity is paid; the garbage collector collects the rent later."] = "make([]int, len(a)) 然后 copy。分配就是支付空间复杂度的地方；垃圾回收器稍后来收租。",
  ["make(chan string). Unbuffered: send waits for receive."] = "make(chan string)。无缓冲：发送要等接收。",
  ["map with an i in front, as in iterator. There is an _unordered twin that is faster."] = "map 前面加个 i，取 iterator 之意。还有一个更快的 _unordered 孪生版本。",
  ["map, then [key type], then value type."] = "map，然后 [键类型]，再是值类型。",
  ["map[K]bool is the everyday set. Missing keys read as false."] = "map[K]bool 是日常用的 set。不存在的键读出来是 false。",
  ["map[string]bool as a set: one O(1) lookup per guest, O(n) total. Fifty million checks become ten thousand."] = "map[string]bool 当集合：每位客人一次 O(1) 查找，总共 O(n)。五千万次检查变成一万次。",
  ["map[string]int. make(map[string]int) if you start empty."] = "map[string]int。从空开始就用 make(map[string]int)。",
  ["map[string]int: hash, bucket, compare. O(1) average, O(n) worst when everything collides. Python's dict, Rust's HashMap."] = "map[string]int：哈希、桶、比较。平均 O(1)，全部碰撞时最差 O(n)。Python 的 dict，Rust 的 HashMap。",
  ["maps.Keys and maps.Values return iter.Seq, so range works on them directly."] = "maps.Keys 和 maps.Values 返回 iter.Seq，所以可以直接 range。",
  ['match a.binary_search(&x) {     // ___\n    Ok(i) => println!("at {i}"),\n    Err(i) => println!("insert at {i}"),\n}\n'] = 'match a.binary_search(&x) {     // ___\n    Ok(i) => println!("at {i}"),\n    Err(i) => println!("insert at {i}"),\n}\n',
  ["match code { 1 => ..., _ => ... } Each arm is pattern => value. The compiler checks every case is covered."] = "match code { 1 => ..., _ => ... } 每个分支是 模式 => 值。编译器检查每种情况都被覆盖。",
  ["matches!(v, Pat) expands to match v { Pat => true, _ => false }. Guards allowed: Some(n) if n > 3."] = "matches!(v, Pat) 展开成 match v { Pat => true, _ => false }。允许守卫：Some(n) if n > 3。",
  ["max := prices[0]\nfor _, p := range prices[1:] {   // ___ comparisons\n    if p > max {\n        max = p\n    }\n}\n"] = "max := prices[0]\nfor _, p := range prices[1:] {   // ___ 次比较\n    if p > max {\n        max = p\n    }\n}\n",
  ["memo = {}\ndef fib(n):\n    if n in ___:\n        return memo[n]\n    v = n if n < 2 else fib(n - 1) + fib(n - 2)\n    memo[n] = v\n    return v\n"] = "memo = {}\ndef fib(n):\n    if n in ___:\n        return memo[n]\n    v = n if n < 2 else fib(n - 1) + fib(n - 2)\n    memo[n] = v\n    return v\n",
  ["memo.get(&n) is O(1). Hit: return it. Miss: compute it. That is memoization."] = "memo.get(&n) 是 O(1)。命中就返回，未命中就算一次。这就是 memoization。",
  ["memo.get(&n) is O(1). Hit: return. Miss: compute and insert. Go spells this the comma-ok test; Python @functools.cache."] = "memo.get(&n) 是 O(1)。命中：返回。未命中：计算并 insert。Go 写成 comma-ok 检查；Python 写 @functools.cache。",
  ['menu = ___\nmenu["tea"] = 12\nmenu["noodles"] = 38\nprint(menu["tea"])     # 12\n'] = 'menu = ___\nmenu["tea"] = 12\nmenu["noodles"] = 38\nprint(menu["tea"])     # 12\n',
  ['menu = ___(tea=12, noodles=38)\nprice = menu["tea"]    # hash the key, jump to the slot\n'] = 'menu = ___(tea=12, noodles=38)\nprice = menu["tea"]    # 哈希键，跳到槽位\n',
  ["menu = {\"tea\": 12, \"noodles\": 38}\ndishes = list(menu.___())\nprint(dishes)     # ['tea', 'noodles']\n"] = "menu = {\"tea\": 12, \"noodles\": 38}\ndishes = list(menu.___())\nprint(dishes)     # ['tea', 'noodles']\n",
  ['menu = {"tea": 12, "noodles": 38}\nprint(menu.___("congee", 0))   # 0, no KeyError\n'] = 'menu = {"tea": 12, "noodles": 38}\nprint(menu.___("congee", 0))   # 0，没有 KeyError\n',
  ["menu = {\"tea\": 12, \"toast\": 18}\n___ menu[\"toast\"]\nprint(menu)     # {'tea': 12}\n"] = "menu = {\"tea\": 12, \"toast\": 18}\n___ menu[\"toast\"]\nprint(menu)     # {'tea': 12}\n",
  ['menu: ___[str, float] = {"tea": 12.0}\n'] = 'menu: ___[str, float] = {"tea": 12.0}\n',
  ["min, max and clear joined len, cap, append in Go 1.21."] = "Go 1.21 里 min、max 和 clear 加入了 len、cap、append 的行列。",
  ["module github.com/alex/luckymac\n\ngo 1.23\n\n___ v1.0.1 // wrong price for the tea set\n"] = "module github.com/alex/luckymac\n\ngo 1.23\n\n___ v1.0.1 // 下午茶套餐的价格错了\n",
  ["module github.com/alex/luckymac\n\ngo ___\n"] = "module github.com/alex/luckymac\n\ngo ___\n",
  ['module github.com/alex/luckymac/___\n\n// callers: import "github.com/alex/luckymac/___/menu"\n'] = 'module github.com/alex/luckymac/___\n\n// 调用方：import "github.com/alex/luckymac/___/menu"\n',
  ["module github.com/siuming/cousinshop\n\ngo 1.23\n\n___ github.com/alex/luckymac v1.2.0\n"] = "module github.com/siuming/cousinshop\n\ngo 1.23\n\n___ github.com/alex/luckymac v1.2.0\n",
  ["module, go, require. go.sum next to it holds the checksums."] = "module、go、require。旁边的 go.sum 存着校验和。",
  ["most_common uses heapq.nlargest inside when k is given. Count in O(n), pick in O(n log k). Round four to Bo."] = "给了 k 时 most_common 内部用 heapq.nlargest。O(n) 计数，O(n log k) 挑选。第四回合归 Bo。",
  ["move || captures by value. Without it the closure would borrow order, and a borrow cannot be proven to outlive the thread."] = "move || 按值捕获。没有它闭包只会借用 order，而借用无法证明活得比线程久。",
  ["mp.Process is a whole python interpreter of its own. It costs milliseconds to start, not microseconds: give it work worth the trip."] = "mp.Process 本身就是一整个 python 解释器。启动它要花毫秒，而不是微秒：给它值得跑这一趟的活儿。",
  ["mp.Queue is safe for many producers and many consumers. It must be created in the parent and passed in as an argument, never made inside the child."] = "mp.Queue 对多生产者多消费者都是安全的。它必须在父进程里创建、作为参数传进去，绝不能在子进程里造。",
  ["mp.Value('i', 0) is four bytes of shared memory with a type code. The object is shared; the number inside it is what you touch."] = "mp.Value('i', 0) 是四个字节的共享内存加一个类型码。共享的是那个对象；你碰的是里面那个数字。",
  ["mp.cpu_count() is Go's runtime.NumCPU(). It counts logical cores, so on a laptop with hyper-threading it is twice the physical ones."] = "mp.cpu_count() 就是 Go 的 runtime.NumCPU()。它数的是逻辑核，所以在有超线程的笔记本上是物理核的两倍。",
  ["mpsc: multi-producer, single-consumer. Job is Send so it may cross to another thread; FnOnce because each ticket runs once."] = "mpsc：多生产者，单消费者。Job 是 Send，所以能跨到另一个线程；用 FnOnce 是因为每张单只跑一次。",
  ["mpsc::channel gives a Sender and a Receiver. Clone the Sender for many producers; the loop ends when all are dropped."] = "mpsc::channel 给一个 Sender 和一个 Receiver。clone Sender 得到多个生产者；全部 drop 后循环结束。",
  ["mpsc::channel() returns (Sender<T>, Receiver<T>). mpsc: multi-producer, single-consumer. The pipe is unbounded."] = "mpsc::channel() 返回 (Sender<T>, Receiver<T>)。mpsc：多生产者，单消费者。这根管子没有上限。",
  ["mu.Lock()\ndefer mu.___()          // even on panic\ncount++\n"] = "mu.Lock()\ndefer mu.___()          // panic 时也执行\ncount++\n",
  ['mu.Lock()\nmenu["set"] = 42\nmu.Unlock()\n\nmu.___()\n'] = 'mu.Lock()\nmenu["set"] = 42\nmu.Unlock()\n\nmu.___()\n',
  ["multiprocessing copies the threading API onto processes, so the code looks the same and the cores actually fill up."] = "multiprocessing 把 threading 的 API 搬到了进程上，所以代码看起来一样，而核心真的被填满了。",
  ["multiprocessing.Process(target=f, args=(x,)) is threading's API on a real process: start() forks or spawns it, join() waits, exitcode says how it went and daemon=True lets it die with the parent. Under the spawn start method the child imports your file again, so everything that runs must sit behind if __name__ == '__main__'."] = "multiprocessing.Process(target=f, args=(x,)) 是把 threading 的 API 放在真正的进程上：start() 用 fork 或 spawn 启动它，join() 等待，exitcode 说明结果如何，daemon=True 让它随父进程一起死。在 spawn 启动方式下，子进程会再次 import 你的文件，所以所有会执行的东西都必须放在 if __name__ == '__main__' 后面。",
  ["mypy runs no code; it reads the hints. Go and Rust do this in the compiler; Python does it on request. The labels print right."] = "mypy 不运行代码；它读标注。Go 和 Rust 在编译器里做；Python 按需做。标签打印正确了。",
  ["n := 7\nhalf := ___(n) / 2      // 3.5, not 3\n"] = "n := 7\nhalf := ___(n) / 2      // 3.5，不是 3\n",
  ["n := runtime.___()\nfor i := 0; i < n; i++ {\n    go worker(jobs, done)\n}\n"] = "n := runtime.___()\nfor i := 0; i < n; i++ {\n    go worker(jobs, done)\n}\n",
  ['n = 4\nprint(___"tables open: {n}")\n'] = 'n = 4\nprint(___"tables open: {n}")\n',
  ["n doubles from 1000 to 2000 items. An O(1) operation takes how long compared to before, in one word?"] = "n 从 1000 翻倍到 2000。O(1) 的操作和之前比要多长时间，一个词？",
  ["n in memo is O(1). Hit: return it. Miss: compute, store, return. That is memoization, spelled out."] = "n in memo 是 O(1)。命中：返回。未命中：计算、存储、返回。这就是写全了的记忆化。",
  ["n is an int. Divide it as a floating point number. Fill: half := ___(n) / 2"] = "n 是 int。把它当浮点数来除。填空：half := ___(n) / 2",
  ["n pushes and pops on a heap of k: O(n log k) time, O(k) space. Sorting would be O(n log n) and O(n)."] = "在大小为 k 的堆上做 n 次 push 和 pop：O(n log k) 时间，O(k) 空间。排序则是 O(n log n) 和 O(n)。",
  ["n times the logarithm of n. No comparison sort can beat it in the worst case."] = "n 乘 n 的对数。没有比较排序能在最差情况下打败它。",
  ["n+1 distinct inputs, each solved once. Linear, without the O( )."] = "n+1 个不同的输入，每个解一次。线性，去掉 O( )。",
  ['n, ___ := prices["hashbrown"]\nif !___ {\n    // missing\n}\n'] = 'n, ___ := prices["hashbrown"]\nif !___ {\n    // 不存在\n}\n',
  ["n-1 comparisons, which is O(n): you cannot know the max without seeing every value. The diagonal is drawn."] = "n-1 次比较，也就是 O(n)：不看遍每个值就不可能知道最大值。对角线画好。",
  ["n-1 comparisons, which is O(n): you cannot know the max without seeing every value. iter().max() does exactly this."] = "n-1 次比较，也就是 O(n)：不看遍每个值就不可能知道最大值。iter().max() 做的正是这个。",
  ["n-1 comparisons, which is O(n): you cannot know the max without seeing every value. max() does exactly this."] = "n-1 次比较，也就是 O(n)：不看遍每个值就不可能知道最大值。max() 做的正是这个。",
  ['name = ___("Order for: ")\nprint(f"one bowl for {name}")\n'] = 'name = ___("Order for: ")\nprint(f"one bowl for {name}")\n',
  ['names := []string{"Wing", "Bo", "Mei"}\nsort.___(names)          // O(n log n)\nfmt.Println(names)       // [Bo Mei Wing]\n'] = 'names := []string{"Wing", "Bo", "Mei"}\nsort.___(names)          // O(n log n)\nfmt.Println(names)       // [Bo Mei Wing]\n',
  ['names = ["Mei", "Alex", "Mei", "Ken"]\nunique = ___(names)\nprint(len(unique))     # 3\n'] = 'names = ["Mei", "Alex", "Mei", "Ken"]\nunique = ___(names)\nprint(len(unique))     # 3\n',
  ['names = ["egg", "tea"]\nqtys = [2, 1]\nfor name, qty in ___(names, qtys):\n    print(qty, "x", name)\n'] = 'names = ["egg", "tea"]\nqtys = [2, 1]\nfor name, qty in ___(names, qtys):\n    print(qty, "x", name)\n',
  ['names = ["noodles", "tea", "toast"]\nshort_first = ___(names, key=len)    # O(n log n)\n'] = 'names = ["noodles", "tea", "toast"]\nshort_first = ___(names, key=len)    # O(n log n)\n',
  ["net/http: handlers and a server"] = "net/http：handler 与服务器",
  ["next() on an exhausted generator raises which exception?"] = "对用尽的生成器调用 next() 抛出哪个异常？",
  ["next(gen) runs to the next yield. next(gen, None) returns None at the end instead of raising."] = "next(gen) 运行到下一个 yield。next(gen, None) 在末尾返回 None 而不是抛错。",
  ["nil check first, then recurse. insert returns the (possibly new) subtree root."] = "先判 nil 再递归。insert 返回（可能是新的）子树根。",
  ["nlargest(n, xs, key=...) is O(n log k) and takes a key. sorted(xs)[-3:] would be O(n log n)."] = "nlargest(n, xs, key=...) 是 O(n log k)，还接受 key。sorted(xs)[-3:] 会是 O(n log n)。",
  ["not st first: pop on an empty list raises IndexError. Then compare with the opener the dict expects."] = "先 not st：对空列表 pop 会抛 IndexError。然后和 dict 期望的开括号比较。",
  ['note = ___          # nothing yet\nif not note:\n    print("no note")\n'] = 'note = ___          # 暂时没有\nif not note:\n    print("no note")\n',
  ['o := Order{Item: "set", Price: 25}\nfmt.Printf("___\\n", o)    // {Item:set Price:25}\n'] = 'o := Order{Item: "set", Price: 25}\nfmt.Printf("___\\n", o)    // {Item:set Price:25}\n',
  ["o.label() passes o as self automatically. Forgetting self is the most common TypeError in a beginner's class."] = "o.label() 自动把 o 作为 self 传入。忘写 self 是初学者类里最常见的 TypeError。",
  ["ok is false only when the channel is closed and drained. It says nothing about the value: that one is always the zero value."] = "只有当 channel 已关闭且取空时 ok 才是 false。它对那个值只字未提：那个值永远是零值。",
  ["ok, an underscore, then the word you use to offer an alternative."] = "ok，下划线，然后是提供备选时用的那个词。",
  ["ok_or(err) maps Some(v) to Ok(v) and None to Err(err). Now ? works on it too."] = "ok_or(err) 把 Some(v) 映射成 Ok(v)，None 映射成 Err(err)。现在 ? 也能用在它上面了。",
  ['omit + empty, one word, after the comma. json:"-" hides a field entirely.'] = 'omit 加 empty，一个词，放在逗号后面。json:"-" 会把字段完全隐藏。',
  ['omitempty drops zero values. "-" drops the field always.'] = 'omitempty 丢掉零值。"-" 总是丢掉该字段。',
  ["once.Do(f) runs f the first time and blocks the rest until it returns, so nobody sees a half-loaded menu."] = "once.Do(f) 第一次运行 f，其余的都被挡住直到它返回，所以没人会看到加载了一半的菜单。",
  ["or, underscore, insert. Takes the starting value and returns &mut u32, which the * dereferences."] = "or、下划线、insert。接收起始值，返回 &mut u32，前面的 * 再解引用。",
  ["or_ plus the word for Default::default(). An empty Vec is the default Vec."] = "or_ 加上 Default::default() 的那个词。空的 Vec 就是默认的 Vec。",
  ["or_insert returns &mut usize, so the * dereferences and += 1 bumps it in place. O(n) to count."] = "or_insert 返回 &mut usize，所以 * 解引用，+= 1 就地加一。计数 O(n)。",
  ['order = ["noodles", "egg", "tea"]\nif "egg" ___ order:\n    print("fry one")\n'] = 'order = ["noodles", "egg", "tea"]\nif "egg" ___ order:\n    print("fry one")\n',
  ["order('noodles', spicy=True, egg=2): how is the parameter written to collect any keyword options?"] = "order('noodles', spicy=True, egg=2)：参数怎么写才能收集任意关键字选项？",
  ["order.total should read like an attribute but be computed. Which built-in decorator?"] = "order.total 读起来要像属性，但要计算出来。哪个内置装饰器？",
  ["ordered = sorted(amounts)    # ___ : Timsort\n"] = "ordered = sorted(amounts)    # ___ ：Timsort\n",
  ["orders = [(\"tea\", 12), (\"noodles\", 38), (\"egg\", 6)]\ncheap = sorted(orders, key=___ o: o[1])\nprint(cheap[0])     # ('egg', 6)\n"] = "orders = [(\"tea\", 12), (\"noodles\", 38), (\"egg\", 6)]\ncheap = sorted(orders, key=___ o: o[1])\nprint(cheap[0])     # ('egg', 6)\n",
  ["orders = ___\nselect {\ncase o := <-orders:\n    cook(o)\ncase <-quit:\n    return\n}\n"] = "orders = ___\nselect {\ncase o := <-orders:\n    cook(o)\ncase <-quit:\n    return\n}\n",
  ["orders.push(18). pop() takes the last one back. The Vec reallocates when it runs out of room."] = "orders.push(18)。pop() 把最后一个取回来。Vec 空间不够时会重新分配。",
  ['orders: ___[str] = []\norders.append("noodles")\n'] = 'orders: ___[str] = []\norders.append("noodles")\n',
  ["out := [][]int{iv[0]}\nfor _, cur := range iv[1:] {\n    last := out[len(out)-1]\n    if cur[0] <= last[___] {    // they touch or overlap\n"] = "out := [][]int{iv[0]}\nfor _, cur := range iv[1:] {\n    last := out[len(out)-1]\n    if cur[0] <= last[___] {    // 相接或重叠\n",
  ["out := make([]Dish, len(orders))\nfor i := range orders {\n    go func() {\n        out[___] = cook(orders[i])\n    }()\n}\n"] = "out := make([]Dish, len(orders))\nfor i := range orders {\n    go func() {\n        out[___] = cook(orders[i])\n    }()\n}\n",
  ["out = [[9, 12], [13, 15], [16, 18]]\n# the free slots between blocks: (12, 13), (15, 16)\nfree = [(a[1], b[0]) for a, b in zip(out, out[___])]\n"] = "out = [[9, 12], [13, 15], [16, 18]]\n# 块之间的空闲时段：(12, 13), (15, 16)\nfree = [(a[1], b[0]) for a, b in zip(out, out[___])]\n",
  ["out[-1] is the last merged block, [1] its end. The sort guarantees s is never before the block's start."] = "out[-1] 是最后一个合并块，[1] 是它的终点。排序保证 s 绝不早于该块的起点。",
  ['p := ___Order{Item: "set"}   // p is *Order\np.Price = 25                  // Go dereferences for you\n'] = 'p := ___Order{Item: "set"}   // p 是 *Order\np.Price = 25                  // Go 替你解引用\n',
  ["p = mp.Process(target=tail_log)\np.___ = True\np.start()\n"] = "p = mp.Process(target=tail_log)\np.___ = True\np.start()\n",
  ['p.join()\nif p.___ != 0:\n    print("the night batch died")\n'] = 'p.join()\nif p.___ != 0:\n    print("夜间批处理死了")\n',
