  ['skip_serializing_if = "Option::is_none" drops empty fields. default fills them on the way in.'] = 'skip_serializing_if = "Option::is_none" 丢掉空字段。default 在读入时把它们补上。',
  ["slices.Contains, Index, Reverse, Max: the loops you used to write by hand."] = "slices.Contains、Index、Reverse、Max：你以前手写的那些循环。",
  ["slices.Sort is generic: no sort.Strings / sort.Ints per type any more."] = "slices.Sort 是泛型的：不再需要按类型分的 sort.Strings / sort.Ints。",
  ["slow, fast := head, head\nfor fast != nil && fast.Next != nil {\n    slow = slow.Next\n    fast = fast.Next.___\n    if slow == fast { return true }   // cycle\n}\n"] = "slow, fast := head, head\nfor fast != nil && fast.Next != nil {\n    slow = slow.Next\n    fast = fast.Next.___\n    if slow == fast { return true }   // 有环\n}\n",
  ["sold++ is three machine steps. Two goroutines can land between them. Put a lock around it."] = "sold++ 是三条机器指令。两个 goroutine 可以插在中间。给它加把锁。",
  ["sort, an underscore, and the word for 'may reorder equal items'."] = "sort、一条下划线，加上“相等项可能重排”那个词。",
  ["sort, by, key with underscores. The closure returns something Ord; here a u32."] = "sort、by、key，用下划线连起来。闭包返回实现了 Ord 的东西；这里是 u32。",
  ["sort, underscore, the opposite of stable. A pattern-defeating quicksort inside."] = "sort、下划线，stable 的反义词。里面是 pattern-defeating quicksort。",
  ["sort.Ints on n receipts: what does it cost, in Big O?"] = "对 n 张收据 sort.Ints：用 Big O 说代价多少？",
  ["sort.Ints sorts the slice where it is. Extra memory, in Big O: O(___)"] = "sort.Ints 就地排序切片。额外内存，用 Big O 说：O(___)",
  ["sort.Ints(a)                        // once: n log n\nfor _, x := range queries {\n    _, ok := slices.BinarySearch(a, x)   // each: O(___)\n}\n"] = "sort.Ints(a)                        // 一次：n log n\nfor _, x := range queries {\n    _, ok := slices.BinarySearch(a, x)   // 每次：O(___)\n}\n",
  ["sort.Ints(a)    // in place: O(___) extra space\n"] = "sort.Ints(a)    // 原地：额外空间 O(___)\n",
  ["sort.Ints(amounts)    // ___ : pdqsort, comparison-based\n"] = "sort.Ints(amounts)    // ___ ：pdqsort，基于比较\n",
  ["sort.Ints(starts); sort.Ints(ends)\nrooms, e := 0, 0\nfor _, s := range starts {\n    if s ___ ends[e] {      // one meeting already over\n        e++\n    } else {\n        rooms++\n"] = "sort.Ints(starts); sort.Ints(ends)\nrooms, e := 0, 0\nfor _, s := range starts {\n    if s ___ ends[e] {      // 有一场会议已经结束\n        e++\n    } else {\n        rooms++\n",
  ["sort.Slice with a less function. slices.SortFunc is the generic Go 1.21 way."] = "sort.Slice 加一个 less 函数。slices.SortFunc 是 Go 1.21 的泛型写法。",
  ["sort.Slice(iv, func(i, j int) bool {\n    return iv[i][0] ___ iv[j][0]    // earliest start first\n})\n"] = "sort.Slice(iv, func(i, j int) bool {\n    return iv[i][0] ___ iv[j][0]    // 起点最早的在前\n})\n",
  ["sort.Strings(names). Go 1.21's slices.Sort(names) is generic and does the same. Both n log n."] = "sort.Strings(names)。Go 1.21 的 slices.Sort(names) 是泛型的，做同样的事。两者都是 n log n。",
  ["sort.___(orders, func(i, j int) bool {\n    return orders[i].Price < orders[j].Price\n})\n"] = "sort.___(orders, func(i, j int) bool {\n    return orders[i].Price < orders[j].Price\n})\n",
  ["sort_by_key is a stable merge sort, like the one you just wrote. sort_by takes a full comparator instead."] = "sort_by_key 是稳定的归并排序，就像你刚写的那个。sort_by 则接收一个完整的比较函数。",
  ["sort_unstable sorts the Vec where it is. Extra memory, in Big O: O(___)"] = "sort_unstable 就地排序 Vec。额外内存，用 Big O 说：O(___)",
  ["sort_unstable: O(n log n), in place, usually faster than sort. Use sort only when order among equals matters. Combo x5."] = "sort_unstable：O(n log n)，原地进行，通常比 sort 快。只有在相等元素的先后重要时才用 sort。连击 x5。",
  ["sort_unstable: same O(n log n), less memory, usually faster. sort_by_key(|o| o.price) sorts by a field."] = "sort_unstable：同样 O(n log n)，内存更少，通常更快。sort_by_key(|o| o.price) 按字段排序。",
  ["sorted on n receipts: what does it cost, in Big O?"] = "对 n 张收据 sorted：用 Big O 说代价多少？",
  ["sorted() is Timsort: merge sort that notices runs already in order. Still n log n in the worst case."] = "sorted() 是 Timsort：会注意到已经有序的段的归并排序。最差情况仍然 n log n。",
  ["sorted(a) == sorted(b) is O(n log n) and one line. Counter(a) == Counter(b) is O(n) and just as short."] = "sorted(a) == sorted(b) 是 O(n log n)，一行。Counter(a) == Counter(b) 是 O(n)，同样短。",
  ["sorted(names, key=len). The key is called n times, O(n), then Timsort. Both together: n log n."] = "sorted(names, key=len)。key 被调用 n 次，O(n)，然后 Timsort。两者加起来：n log n。",
  ["sorted(xs) returns a new list, xs.sort() sorts in place. Both take key= and reverse=True. The rack is in order."] = "sorted(xs) 返回新列表，xs.sort() 就地排序。两者都接受 key= 和 reverse=True。货架整齐了。",
  ["spawn returns a handle you can wait on. What is its type?"] = "spawn 返回一个可以等待的句柄。它的类型是什么？",
  ["spawn starts a clean interpreter and pickles the target across, so nothing is silently inherited. fork is faster and shares everything, including locks held at the wrong moment."] = "spawn 启动一个干净的解释器，并把 target 用 pickle 送过去，所以不会有东西被悄悄继承。fork 更快，而且什么都共享，包括在错误时刻被持有的锁。",
  ["split, underscore, at. Panics if mid is past the end; here it never is."] = "split、下划线、at。mid 超过末尾就会 panic；这里永远不会。",
  ["split_at gives (&v[..mid], &v[mid..]) as one tuple. Two shared borrows of one slice are fine."] = "split_at 用一个元组给出 (&v[..mid], &v[mid..])。对同一个切片做两次共享借用没问题。",
  ["st := []rune{}\nfor _, c := range s {\n    if _, closer := pairs[c]; !closer {\n        st = ___(st, c)     // an opener waits here\n        continue\n    }\n}\n"] = "st := []rune{}\nfor _, c := range s {\n    if _, closer := pairs[c]; !closer {\n        st = ___(st, c)     // 开括号在这里等着\n        continue\n    }\n}\n",
  ['st = []\nst.append("(")\nst.append("[")\ntop = st[___]        # the most recent opener\nprint(top)           # [\n'] = 'st = []\nst.append("(")\nst.append("[")\ntop = st[___]        # 最近的开括号\nprint(top)           # [\n',
  ["st[-1] is the peek. Guard it with if st: the same way as pop."] = "st[-1] 就是窥视。像 pop 一样用 if st: 守着它。",
  ["starmap(f, [(a, b), ...]) calls f(a, b). It is the difference between one argument and several, and the reason you rarely need a wrapper function."] = "starmap(f, [(a, b), ...]) 调用的是 f(a, b)。这就是一个参数和多个参数的区别，也是你很少需要写包装函数的原因。",
  ["start:stop, the stop is not included. Same rule as Go's a[1:3]."] = "start:stop，stop 不包含在内。和 Go 的 a[1:3] 同一规则。",
  ['str(4) is "4". "Table " + 4 raises TypeError: Python never converts silently. The stock count comes out whole.'] = 'str(4) 是 "4"。"Table " + 4 抛出 TypeError：Python 从不悄悄转换。库存数终于是整数了。',
  ["strconv.Atoi / Itoa for ints, ParseFloat and FormatFloat for floats."] = "int 用 strconv.Atoi / Itoa，float 用 ParseFloat 和 FormatFloat。",
  ["string is bytes, rune is a code point. utf8 counts characters, strconv converts."] = "string 是字节，rune 是码点。utf8 数字符，strconv 做转换。",
  ["strings has Split, Join, Contains, TrimSpace, ToUpper... all return new strings."] = "strings 有 Split、Join、Contains、TrimSpace、ToUpper……都返回新的 string。",
  ['struct Grill;\n// Grill promises every method of Cook.\nimpl Cook ___ Grill {\n    fn name(&self) -> String {\n        "grill".to_string()\n    }\n}\n'] = 'struct Grill;\n// Grill 承诺实现 Cook 的每个方法。\nimpl Cook ___ Grill {\n    fn name(&self) -> String {\n        "grill".to_string()\n    }\n}\n',
  ["struct ListNode {\n    val: i32,\n    next: ___<Box<ListNode>>,   // the rest, or the end\n}\n"] = "struct ListNode {\n    val: i32,\n    next: ___<Box<ListNode>>,   // 剩下的部分，或者到头了\n}\n",
  ["struct Order { id: u32, price: u32 }\nlet mut orders = vec![\n    Order { id: 7, price: 45 },\n    Order { id: 3, price: 18 },\n];\n// cheapest first; equal prices keep their order (stable)\norders.___(|o| o.price);\n"] = "struct Order { id: u32, price: u32 }\nlet mut orders = vec![\n    Order { id: 7, price: 45 },\n    Order { id: 3, price: 18 },\n];\n// 最便宜的在前；价格相同的保持原序（稳定）\norders.___(|o| o.price);\n",
  ["struct Order { item: String, qty: u32 } Fields are private to the module unless marked pub."] = "struct Order { item: String, qty: u32 } 字段对模块私有，除非标 pub。",
  ["struct Order { qty: u32 }\n\n___ Order {\n    fn total(&self) -> u32 {\n        self.qty * 18\n    }\n}\n"] = "struct Order { qty: u32 }\n\n___ Order {\n    fn total(&self) -> u32 {\n        self.qty * 18\n    }\n}\n",
  ["struct Receipt<'a> { name: &'a str }: a Receipt cannot outlive the name it borrows. The compiler now checks it for you."] = "struct Receipt<'a> { name: &'a str }：Receipt 不能活得比它借的名字久。现在编译器替你检查。",
  ['struct Wok;\nimpl Cook for Wok {\n    fn name(&self) -> String { "wok".to_string() }\n}\n// Any Cook, decided at run time, behind a reference.\nfn call(c: &___ Cook) { println!("{}", c.greet()); }\ncall(&Grill); call(&Wok);\n'] = 'struct Wok;\nimpl Cook for Wok {\n    fn name(&self) -> String { "wok".to_string() }\n}\n// 任何 Cook，运行时决定，放在引用后面。\nfn call(c: &___ Cook) { println!("{}", c.greet()); }\ncall(&Grill); call(&Wok);\n',
  ["struct groups fields. *T is a pointer. Methods have a receiver. interface is a set of methods."] = "struct 组合字段。*T 是指针。方法有接收者。interface 是一组方法。",
  ["struct groups fields. impl adds methods that take &self or &mut self. enum lists variants; match handles them all."] = "struct 把字段组合起来。impl 添加接收 &self 或 &mut self 的方法。enum 列出变体；match 全部处理。",
  ["struct, impl and enum"] = "struct、impl 与 enum",
  ["submit(f, *args) is go f(args): the call is already running somewhere else and you hold the receipt."] = "submit(f, *args) 就是 go f(args)：这次调用已经在别处跑着，而你手里拿着收据。",
  ["sum := 0\nfor _, p := range prices {    // ___ : n items, n adds\n    sum += p\n}\n"] = "sum := 0\nfor _, p := range prices {    // ___ ：n 项，n 次加\n    sum += p\n}\n",
  ["sum over n prices: what is the cost in Big O?"] = "对 n 个价格 sum：用 Big O 说代价多少？",
  ["sum takes any number of fares. Fill the parameter type: fares ___"] = "sum 接受任意数量的车费。填入参数类型：fares ___",
  ["sum.golang.org records the hash of every public version once, so two people who go get the same tag either get identical bytes or an error."] = "sum.golang.org 把每个公开版本的哈希记录一次，所以两个人 go get 同一个标签，要么拿到完全相同的字节，要么得到错误。",
  ["sum::<i32>() adds &i32 into an i32. Without the turbofish Rust cannot pick the type."] = "sum::<i32>() 把 &i32 加成一个 i32。没有 turbofish，Rust 选不出类型。",
  ["super().__init__(item) runs the parent constructor. class SetMeal(Order) is inheritance; Go embeds instead."] = "super().__init__(item) 运行父类构造器。class SetMeal(Order) 是继承；Go 用嵌入代替。",
  ['switch light { case "green": walk() }. No break: cases do not fall through.'] = 'switch light { case "green": walk() }。不用 break：case 不会贯穿。',
  ["switch v.(type) gives x the concrete type in every case."] = "switch v.(type) 在每个 case 里都给 x 具体类型。",
  ['switch x := v.(___) {\ncase int:\n    fmt.Println(x + 1)      // x is an int here\ncase string:\n    fmt.Println(x + "!")    // and a string here\n}\n'] = 'switch x := v.(___) {\ncase int:\n    fmt.Println(x + 1)      // 这里 x 是 int\ncase string:\n    fmt.Println(x + "!")    // 这里是 string\n}\n',
  ["sync, underscore, then the word for the pipe itself."] = "sync，下划线，然后是管子本身的那个词。",
  ["sync.Map pays off for keys written once and read often. For anything else a plain map behind a Mutex is faster and clearer."] = "sync.Map 适合写一次、读很多次的键。其他情况下，用 Mutex 包住普通 map 更快也更清楚。",
  ["sync.Mutex. Lock, change, Unlock. Prefer channels when you can."] = "sync.Mutex。Lock、修改、Unlock。能用 channel 就优先用 channel。",
  ["sync.Mutex: one goroutine at a time"] = "sync.Mutex：一次只有一个 goroutine",
  ["sync.Once.Do runs the function once and blocks the others until it finishes. Go 1.21 adds sync.OnceValue."] = "sync.Once.Do 只运行函数一次，其他调用者阻塞到它完成。Go 1.21 新增 sync.OnceValue。",
  ["sync.OnceValue(f) returns a function: the first call runs f, every later call returns the cached value. sync.OnceValues does the (T, error) pair."] = "sync.OnceValue(f) 返回一个函数：第一次调用运行 f，之后每次都返回缓存的值。(T, error) 那一对用 sync.OnceValues。",
  ["sync.Pool recycles short-lived allocations across goroutines. It is a garbage-collector optimisation, never a place to keep state."] = "sync.Pool 在 goroutine 之间回收短命的分配。它是垃圾回收的优化，绝不是存放状态的地方。",
  ["sync.RWMutex: any number of RLock holders, or exactly one Lock holder. Worth it when reads dominate."] = "sync.RWMutex：RLock 的持有者可以有任意多个，Lock 的持有者只能有一个。读远多于写时才划算。",
  ["sync/atomic is for single words: counters, flags. Anything bigger wants a Mutex."] = "sync/atomic 用于单个机器字：计数器、标志位。再大的就要用 Mutex。",
  ["sync_channel(n) is bounded: send blocks when n values wait. Backpressure, like a buffered Go channel. The queue moves."] = "sync_channel(n) 有上限：n 个值在等时 send 阻塞。背压，就像带缓冲的 Go channel。队伍动起来了。",
  ['t = threading.Thread(target=fry, args=("egg",))\nt.___()\nprint("frying in the background")\n'] = 't = threading.Thread(target=fry, args=("egg",))\nt.___()\nprint("frying in the background")\n',
  ["t.Errorf marks failure and continues; t.Fatalf stops. Table tests loop over cases with t.Run."] = "t.Errorf 标记失败并继续；t.Fatalf 会停止。表驱动测试用 t.Run 遍历各个用例。",
  ["t.start() spawns the OS thread and returns at once. t.run() is the body; calling it yourself gains nothing."] = "t.start() 生成 OS 线程并立刻返回。t.run() 是主体；自己调用它毫无收获。",
  ['table = 4\nlabel = "Table " + ___(table)\nprint(label)       # Table 4\n'] = 'table = 4\nlabel = "Table " + ___(table)\nprint(label)       # Table 4\n',
  ["thiserror derives Display + Error; #[from] even writes the From impl. Ticket two closed."] = "thiserror 帮你 derive Display + Error；#[from] 连 From impl 都替你写好。第二张工单关闭。",
  ["thread::scope(|s| ...) joins every s.spawn before returning, so the closures may borrow without move. Three cooks, one menu."] = "thread::scope(|s| ...) 返回前 join 每个 s.spawn，所以闭包不用 move 就能借用。三个厨师，一份菜单。",
  ["thread::sleep(Duration) takes a Duration, never a bare number. Duration::from_secs and from_millis build one."] = "thread::sleep(Duration) 接收 Duration，从不接收裸数字。Duration::from_secs 和 from_millis 能造一个。",
  ["thread::spawn returns JoinHandle<T>. Keep them in a Vec, or the threads are detached and main may exit first."] = "thread::spawn 返回 JoinHandle<T>。把它们收在一个 Vec 里，不然线程就脱了管，main 可能先退出。",
  ["thread::spawn starts a thread; move gives it its data; join waits. thread::scope may borrow."] = "thread::spawn 启动线程；move 把数据交给它；join 等待。thread::scope 可以借用。",
  ["thread::spawn(closure) returns a JoinHandle and runs at once on an OS thread. Rust has no green threads built in."] = "thread::spawn(closure) 返回 JoinHandle，立刻在操作系统线程上运行。Rust 没有内建绿色线程。",
  ["threading.Thread(target=f).start() runs f beside the main thread; join waits. Lock guards shared state. ThreadPoolExecutor manages a pool. The GIL lets one thread run bytecode at a time."] = "threading.Thread(target=f).start() 在主线程旁运行 f；join 等待。Lock 守护共享状态。ThreadPoolExecutor 管理一个池。GIL 让一次只有一个线程运行字节码。",
  ["tidy walks every import in the module, adds what is missing to go.mod and go.sum and drops what nothing uses. Run it before every commit."] = "tidy 遍历模块里的每个 import，把缺的加进 go.mod 和 go.sum，把没人用的删掉。每次提交前都跑一遍。",
  ["time.After in a select is the classic timeout. In a loop prefer a time.Timer."] = "select 里的 time.After 是经典超时写法。循环里最好用 time.Timer。",
  ["tokio::spawn needs a 'static + Send future. handle.await gives Result<T, JoinError>."] = "tokio::spawn 需要 'static + Send 的 future。handle.await 给出 Result<T, JoinError>。",
  ["top = prices[0]\nfor p in prices[1:]:    # ___ comparisons\n    if p > top:\n        top = p\n"] = "top = prices[0]\nfor p in prices[1:]:    # ___ 次比较\n    if p > top:\n        top = p\n",
  ["total = 0\n\ndef add(rows):\n    global total\n    total += sum(rows)\n# the child changed its own ___ of total\n"] = "total = 0\n\ndef add(rows):\n    global total\n    total += sum(rows)\n# 子进程只改了自己那份 total 的 ___\n",
  ["total = sum(prices)    # ___ : n items, n adds, inside C\n"] = "total = sum(prices)    # ___ ：n 项，n 次加，在 C 里\n",
  ["total = sum(prices)    # n steps\ntop = max(prices)      # n more\n# 2n steps, written O(___)\n"] = "total = sum(prices)    # n 步\ntop = max(prices)      # 再 n 步\n# 2n 步，写作 O(___)\n",
  ["total only reads the order. Which receiver borrows it without change?"] = "total 只读订单。哪个接收者借用它而不修改？",
  ["total(3, 5) and total(3, 5, 8) should both work. How is the parameter written to take any number of items?"] = "total(3, 5) 和 total(3, 5, 8) 都要能用。参数怎么写才能接受任意数量的项？",
  ["trait Cook lists methods. One with a body is a default; implementors may keep it or override it."] = "trait Cook 列出方法。带函数体的是默认实现；实现者可以保留或覆盖。",
  ['tray := []string{"muffin", "hash", "coffee", "tea"}\ntwo := tray[___]         // {"hash", "coffee"}\n'] = 'tray := []string{"muffin", "hash", "coffee", "tea"}\ntwo := tray[___]         // {"hash", "coffee"}\n',
  ['tray := []string{"muffin", "hashbrown"}\nn := ___(tray)         // 2\n'] = 'tray := []string{"muffin", "hashbrown"}\nn := ___(tray)         // 2\n',
  ['tray := []string{"muffin"}\ntray = ___(tray, "hashbrown")\n'] = 'tray := []string{"muffin"}\ntray = ___(tray, "hashbrown")\n',
  ['tray := ___([]string, 0, 8)   // len 0, cap 8\ntray = append(tray, "muffin")\n'] = 'tray := ___([]string, 0, 8)   // len 0，cap 8\ntray = append(tray, "muffin")\n',
  ["tray := make([]string, 2, 8)\nfmt.Println(len(tray), ___(tray))   // 2 8\n"] = "tray := make([]string, 2, 8)\nfmt.Println(len(tray), ___(tray))   // 2 8\n",
  ["tray = append(tray, x). Never ignore the return."] = "tray = append(tray, x)。永远别忽略返回值。",
  ["trays = [\"egg\", \"tea\", \"toast\", \"rice\"]\nprint(trays[___])     # ['tea', 'toast']\n"] = "trays = [\"egg\", \"tea\", \"toast\", \"rice\"]\nprint(trays[___])     # ['tea', 'toast']\n",
  ['trays = ["egg", "tea", "toast", "rice"]\nprint(trays[___])     # rice\n'] = 'trays = ["egg", "tea", "toast", "rice"]\nprint(trays[___])     # rice\n',
  ['trays = ["egg", "tea", "toast"]\nit = ___(trays)\nprint(next(it))     # egg\nprint(next(it))     # tea\n'] = 'trays = ["egg", "tea", "toast"]\nit = ___(trays)\nprint(next(it))     # egg\nprint(next(it))     # tea\n',
  ['trays = ["egg", "tea", "toast"]\nprint(___(trays))     # 3\n'] = 'trays = ["egg", "tea", "toast"]\nprint(___(trays))     # 3\n',
  ["trays = [\"egg\", \"tea\"]\ntrays.___(\"toast\")\nprint(trays)     # ['egg', 'tea', 'toast']\n"] = "trays = [\"egg\", \"tea\"]\ntrays.___(\"toast\")\nprint(trays)     # ['egg', 'tea', 'toast']\n",
  ["trays.append(x) is amortized O(1). trays = trays.append(x) is the classic bug: it sets trays to None."] = "trays.append(x) 是摊还 O(1)。trays = trays.append(x) 是经典 bug：它把 trays 设成 None。",
  ["tree.as_ref() turns &Option<T> into Option<&T>. Without it, map would try to move out of the borrow."] = "tree.as_ref() 把 &Option<T> 变成 Option<&T>。没有它，map 会试图从借用里把值移走。",
  ["try, except, raise"] = "try、except、raise",
  ["try, underscore, then the blocking method's name."] = "try，下划线，然后是那个阻塞方法的名字。",
